L2_1.m_Pos = "C"
L2_1.m_Talk_KOREA = "라우라, 잠깐 나와 봐. 손님이야."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "ラウラ、ちょっと来て。お客さんだわ。"
L2_1.m_Talk_ENG = "Laura, come on out here for a second. We've got a customer."
L2_1.m_Talk_TWN = "蘿拉，妳出來一下，有客人。"
L2_1.m_Talk_THA = "ลอร่า มานี่แป๊บหนึ่งสิ เรามีลูกค้า"
L2_1.m_Talk_VTN = "Laura, ra đây một chút. Chúng ta có khách này."
L2_1.m_Talk_SCN = "劳拉，出来一下，有客人。"
L2_1.m_Talk_DEU = "Laura, komm mal kurz her. Wir haben Kundschaft."
L2_1.m_Talk_FRA = "Laura, tu peux venir une seconde ? On a une cliente."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 31354
L3_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "마감 시간에 웬 손님이람. 커피 한 잔 주고 돌려보내."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "閉店時間に客だと？　コーヒー一杯渡して送り返せ。"
L3_1.m_Talk_ENG = "But it's nearly closing time. Just give them a cup of coffee on the house and kick them out."
L3_1.m_Talk_TWN = "都到要下班了怎麼還有客人。給杯咖啡打發他回去吧。"
L3_1.m_Talk_THA = "แต่นี่ใกล้เวลาร้านปิดแล้วนะ แค่เลี้ยงกาแฟสักถ้วยแล้วไล่กลับบ้านซะ"
L3_1.m_Talk_VTN = "Nhưng gần đến giờ đóng cửa rồi. Chỉ cần đưa cho họ một tách cà phê và đuổi họ ra ngoài thôi."
L3_1.m_Talk_SCN = "都到要下班了怎么还有客人。给杯咖啡打发回去吧。"
L3_1.m_Talk_DEU = "Gleich ist Feierabend. Eine Tasse Kaffee noch, dann schließen wir."
L3_1.m_Talk_FRA = "Mais on va bientôt fermer. Donne-lui une tasse de café à nos frais et fais-la partir."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 31354
