L4_1.m_Face = "UNIT_LAUGH"
L4_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "아쉽지만 다른 용건이야."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "残念だけど、コーヒーを飲みに来たんじゃないわ。"
L4_1.m_Talk_ENG = "Unfortunately she's here for another reason."
L4_1.m_Talk_TWN = "很可惜，是有別的事情。"
L4_1.m_Talk_THA = "น่าเสียดายที่เธอมาเพราะเหตุผลอื่น"
L4_1.m_Talk_VTN = "Không may là, cô ấy ở đây vì một lý do khác."
L4_1.m_Talk_SCN = "很可惜，是有别的事情。"
L4_1.m_Talk_DEU = "Aber sie ist aus einem anderen Grund hier."
L4_1.m_Talk_FRA = "Malheureusement, elle est ici pour une autre raison."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 31354
L5_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "전단지 돌리는 마녀에게 여기 오면 소원을 이뤄 준다는 얘기를 들었다던데?"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "チラシを配っていた魔女に、ここに来ると願い事を叶えてくれるって聞いたそうよ。"
L5_1.m_Talk_ENG = "She said a witch gave her a pamphlet saying we can grant her wish here."
L5_1.m_Talk_TWN = "她說發傳單的魔女告訴她，只要來到店裡就能實現願望？"
L5_1.m_Talk_THA = "เธอบอกว่ามีแม่มดให้ใบปลิวมา บอกว่าเราทำให้ความปรารถนาของเธอเป็นจริงได้"
L5_1.m_Talk_VTN = "Cô ấy nói là một phù thủy đã đưa cho cô ấy một tờ rơi, và chúng ta có thể ban điều ước cho cô ấy ở đây."
L5_1.m_Talk_SCN = "发传单的魔女说，只要来到店里就能实现愿望？"
L5_1.m_Talk_DEU = "Sie sagt, eine Hexe hat ihr einen Flyer gegeben, auf dem steht, dass wir ihr einen Wunsch gewähren."
L5_1.m_Talk_FRA = "Elle dit qu'une sorcière lui a donné une brochure selon laquelle on exauce les vœux ici."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 31354
