L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "......또 그 바보 소행이구나. 정말 지치지도 않나 보네."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "……またあのバカの仕業か。あいつも懲りないものだ。"
L6_1.m_Talk_ENG = "Ugh, it's that idiot again... She never gives up, does she?"
L6_1.m_Talk_TWN = "……又是那個笨蛋做的好事啊，她真是不會膩耶。"
L6_1.m_Talk_THA = "โอ๊ย ยัยโง่นั่นอีกแล้ว... ไม่เคยยอมแพ้เลยใช่มั้ย?"
L6_1.m_Talk_VTN = "Ugh, lại là tên ngốc đó... Không chịu bỏ cuộc, đúng không?"
L6_1.m_Talk_SCN = "……又是那个笨蛋做的好事啊，她怎么就不会腻呢。"
L6_1.m_Talk_DEU = "Urgh, diese Verrückte schon wieder … Gibt die denn nie auf?"
L6_1.m_Talk_FRA = "Rah, encore cette idiote... Elle n'abandonne donc jamais ?"
