L9_1.m_Face = "UNIT_LAUGH"
L9_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L9_1.m_Pos = "C"
L9_1.m_Crash = 30
L9_1.m_Talk_KOREA = "앗! 아까 그 사람! 바로 와 줬어! 아자! 마케팅의 성공!"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "あっ！　さっきの人ね！　すぐに来てくれたんだ！　やった！　客引き成功！"
L9_1.m_Talk_ENG = "Oh! It's her from before! She really came! Woohoo! My marketing worked!"
L9_1.m_Talk_TWN = "啊！剛才那個人！這麼快就來啦！耶！推銷成功！"
L9_1.m_Talk_THA = "อ๊ะ! คนก่อนหน้านี้นี่! เธอมาจริงๆ ด้วย! ไชโย! การตลาดของฉันได้ผล!"
L9_1.m_Talk_VTN = "Ồ! Là cô ấy! Cô ấy thực sự đến! Tuyệt vời! Chiêu trò của tôi đã có tác dụng!"
L9_1.m_Talk_SCN = "啊！刚才那个人！这么快就来啦！耶！推销成功！"
L9_1.m_Talk_DEU = "Oh! Sie ist es! Sie ist wirklich gekommen. Juchuu! Meine Werbung hat funktioniert!"
L9_1.m_Talk_FRA = "Oh ! C'est celle de la dernière fois ! Elle est vraiment venue ! Super ! Ma pub a marché !"
