L14_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L14_1.m_Pos = "R"
L14_1.m_Crash = 40
L14_1.m_Talk_KOREA = "아야야야! 미안, 플루토! 정어리 사 줄게! 정어리!"
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "あいたたた！　ごめん、プルートー！　イワシ買ってあげるから！　イワシ！"
L14_1.m_Talk_ENG = "Ow! I'm sorry, Pluto! I'll buy you a can of tuna! Tuna!"
L14_1.m_Talk_TWN = "啊啊啊啊！抱歉，布魯托！我會給你買沙丁魚的！沙丁魚！"
L14_1.m_Talk_THA = "โอ๊ย! ขอโทษนะ พลูโต! เดี๋ยวฉันซื้อทูน่าให้ประป๋องนึง! ทูน่าไง!"
L14_1.m_Talk_VTN = "Ối! Tôi xin lỗi, Pluto! Tôi sẽ mua cho bạn một hộp cá ngừ! Cá ngừ!"
L14_1.m_Talk_SCN = "啊啊啊啊！抱歉，布鲁托！我会给你买沙丁鱼的！沙丁鱼！"
L14_1.m_Talk_DEU = "Autsch! Tut mir Leid, Pluto! Ich kauf dir eine Dose Thunfisch! Thunfisch!"
L14_1.m_Talk_FRA = "Aïe ! Désolée, Pluto ! Je t'achèterai une boîte de thon ! Du thon !"
L15_1 = {}
L15_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 31354
L15_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L15_1.m_Pos = "L"
L15_1.m_Talk_KOREA = "야박하게 왜 그래. 지점 낸 뒤로 기념할 만한 첫 손님이잖아."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "薄情なことしないで。支店を出してからの、記念すべき初めてのお客さんでしょ。"
L15_1.m_Talk_ENG = "Don't be so hard on her. It's our first customer after opening this branch."
L15_1.m_Talk_TWN = "不要這麼無情嘛，這可是分店開張後值得紀念的第一位客人耶。"
L15_1.m_Talk_THA = "อย่าใจร้ายกับเธอนักสิ นี่เป็นลูกค้าคนแรกหลังเปิดสาขานี้นะ"
L15_1.m_Talk_VTN = "Đừng làm khó con bé như thế. Đây là khách hàng đầu tiên của chúng ta sau khi mở chi nhánh này đấy."
L15_1.m_Talk_SCN = "不要这么无情嘛，这可是分店开业后值得纪念的第一位客人啊。"
L15_1.m_Talk_DEU = "Sei nicht so hart mit ihr. Sie ist unsere erste Kundin seit der Eröffnung."
L15_1.m_Talk_FRA = "Ne sois pas si dure avec elle. C'est notre première cliente depuis qu'on a ouvert cette succursale."
