L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "정말 여기서 내 소원을 이뤄 줄 수 있어?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "本当にここで私の願い事を叶えてもらえるの？"
L18_1.m_Talk_ENG = "Can you guys really grant my wish here?"
L18_1.m_Talk_TWN = "這裡真的可以實現我的願望嗎？"
L18_1.m_Talk_THA = "พวกคุณทำให้ความปรารถนาของฉันเป็นจริงได้เหรอคะ?"
