L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "......그래. 같은 카운터 능력이라도 어떻게 쓰느냐에 따라 할 수 있는 일이 다르거든."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "……そうだ。同じカウンターでも能力をどう使うかによって、できることが違うからな。"
L19_1.m_Talk_ENG = "Yeah. There's all sorts of ways Counters can use their abilities."
L19_1.m_Talk_TWN = "……沒錯。但就算是同樣的制裁者能力，也會因不同的使用方法獲得不同的結果。"
L19_1.m_Talk_THA = "ได้สิ เคาน์เตอร์ใช้ความสามารถได้หลากหลายรูปแบบเลยนะ"
L19_1.m_Talk_VTN = "Vâng. Các Counter có thể sử dụng khả năng của họ theo nhiều cách."
L19_1.m_Talk_SCN = "……没错。但就算是同样的制裁者能力，也会因不同的使用方法获得不同的结果。"
L19_1.m_Talk_DEU = "Jep. Counter können ihre Fähigkeiten auf die verschiedensten Arten verwenden."
L19_1.m_Talk_FRA = "Ouais. Les Counters peuvent utiliser leurs capacités de façons très variées."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 31354
