L20_1.m_Face = "UNIT_LAUGH"
L20_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "물론 마녀에게 소원을 빌려면 대가가 필요해."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "もちろん、魔女に願い事をするためには対価が必要だ。"
L20_1.m_Talk_ENG = "Of course, you'll have to pay a price if you want a witch to grant you your wish."
L20_1.m_Talk_TWN = "當然，向魔女許願是需要代價的。"
L20_1.m_Talk_THA = "แน่นอนว่าเธอจะต้องจ่ายเงินนะ ถ้าอยากให้แม่มดทำตามความปรารถนาน่ะ"
L20_1.m_Talk_VTN = "Tất nhiên, bạn sẽ phải trả giá nếu muốn một phù thủy ban điều ước cho mình."
L20_1.m_Talk_SCN = "当然，向魔女许愿是需要代价的。"
L20_1.m_Talk_DEU = "Natürlich hat es aber seinen Preis, wenn dir eine Hexe einen Wunsch gewähren soll."
L20_1.m_Talk_FRA = "Bien sûr, pour qu'une sorcière exauce ton vœu, il faut en payer le prix."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_4@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 31354
L21_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L21_1.m_bWaitClick = true
