L21_1.m_Face = "UNIT_PRIDE"
L21_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Crash = 30
L21_1.m_Talk_KOREA = "그리고 난 네가 뭘 주든 절대 안 받을 거야. 메롱."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "それに妾は汝に何を渡されようが、絶対受け取らない。ベーだ。"
L21_1.m_Talk_ENG = "And I won't take any payment from you, no matter what. So get lost."
L21_1.m_Talk_TWN = "還有，無論妳給我什麼我都不會收下的。吐舌頭～"
L21_1.m_Talk_THA = "ซึ่งฉันก็จะไม่รับเงินจากเธอด้วย ไม่ว่ายังไงก็ตาม ดังนั้นก็ไปซะ"
L21_1.m_Talk_VTN = "Và tôi sẽ không nhận bất kỳ khoản thanh toán nào từ bạn, dù đó là gì đi chăng nữa. Vậy nên hãy biến đi."
L21_1.m_Talk_SCN = "还有，无论你给我什么我都绝对不会接受的。略略略~"
L21_1.m_Talk_DEU = "Und von dir werde ich so oder so keine Bezahlung annehmen. Also verschwinde."
L21_1.m_Talk_FRA = "Et je ne compte pas accepter de paiement de ta part, alors dégage."
