L25_1.m_Talk_KOREA = "그러는 넌 급체 걸린 백설공주니?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "そういう汝こそ、急に胃もたれでもした白雪姫か？"
L25_1.m_Talk_ENG = "Think that makes you Snow White or something?"
L25_1.m_Talk_TWN = "那妳就是消化不良的白雪公主囉？"
L25_1.m_Talk_THA = "คิดว่าพูดแล้วจะทำให้ตัวเองเป็นสโนว์ไวท์เหรอ?"
