L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "아, 어디서 봤나 했더니 하트베리였구나?"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "あ、見覚えがあると思ったらハートベリーの子よね？"
L27_1.m_Talk_ENG = "Oh, I knew I've seen you from somewhere! You're HRT Berry, right?"
L27_1.m_Talk_TWN = "啊，我說怎麼這麼眼熟，這不是愛心莓果嗎？"
L27_1.m_Talk_THA = "อ๋อ รู้แล้วว่าเคยเห็นเธอที่ไหน! เธอคือ HRT เบอร์รี่ใช่มั้ย?"
L27_1.m_Talk_VTN = "Ồ, tôi biết là tôi đã thấy bạn rồi mà! Bạn là Quả Mọng Tình Yêu đúng không?"
L27_1.m_Talk_SCN = "啊，我说怎么这么眼熟，这不是爱心莓果吗？"
L27_1.m_Talk_DEU = "Ich wusste doch, dass du mir bekannt vorkommst! Du bist bei HRT Berry, oder?"
L27_1.m_Talk_FRA = "Oh, je savais que je t'avais déjà vue quelque part ! Tu es membre de HRT Berry, pas vrai ?"
