L34_1 = "이렇게 만날 줄은 몰랐어. 혹시 언니가 기념으로 사인 좀 받아도 될까?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "こんな所で会えるなんてね。お姉さんが記念にサインをもらってもいいかな？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I never thought I'd get to meet you like this. Could I get an autograph?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "沒想到會以這種方式見面，姐姐可以向妳要個簽名作紀念嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ไม่เคยคิดเลยว่าจะได้เจอเธอแบบนี้ ขอลายเซ็นได้มั้ย?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi chưa bao giờ nghĩ mình sẽ được gặp bạn như thế này. Tôi có thể xin chữ ký không?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "没想到会以这种方式见面，姐姐可以向你要一个签名作纪念吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich hätte nie gedacht, dass ich dich mal treffen würde. Kann ich ein Autogramm bekommen?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je n'aurais jamais cru te rencontrer comme ça. Je peux avoir un autographe ?"
L33_1.m_Talk_FRA = L34_1
