L37_1 = "이제 진지하게 상담을 들어 줄 수밖에 없겠는데?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "これでもう真剣に相談に乗るしかなくなったわね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I guess we have no choice but to hear her out now!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "這下妳只能認真聽她說了吧？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ท่าทางเราจะไม่มีทางเลือก นอกจากจะฟังเรื่องของเธอแล้วละ!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tôi đoán chúng ta không có lựa chọn nào khác ngoài việc nghe cô ấy nói lúc này!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "现在只能认真听了吧？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich schätze … jetzt müssen wir ihr zuhören!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Je suppose qu'on n'a plus le choix, il faut qu'on l'écoute."
L36_1.m_Talk_FRA = L37_1
