L43_1.m_Face = L44_1
L43_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "그래서, 예전에 헤어진 사람을 다시 만났는데 널 몰라볼 것 같아서 걱정된다고?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それで、前に別れた人と再会したけど、汝のことに気付いてもらえなさそうで心配だと？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "So you finally found the person you've been looking for, but this person doesn't seem to recognize you?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "也就是說，妳遇到了以前和妳分手的人，但他好像不認識妳，所以妳很擔心？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "สรุปว่าเธอพบคนที่ตามหาแล้ว แต่คนนี้ดูจะจำเธอไม่ได้เหรอ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Vậy là cuối cùng bạn đã tìm được người mình muốn, nhưng người này có vẻ như không nhận ra bạn sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "也就是说，你遇到了以前和你分离的人，但他好像不认识你，所以你很担心？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Also hast du endlich die Person gefunden, die du gesucht hast, aber sie erkennt dich nicht wieder?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Alors comme ça, tu as enfin retrouvé la personne que tu cherchais, mais elle n'a pas l'air de te reconnaître ?"
L43_1.m_Talk_FRA = L44_1
