L47_1 = "R_M_I"
L46_1.m_Pos = L47_1
L47_1 = "왠지 낭만적이다~ 언제부터 만나고 싶었어요?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ロマンチックな話だね～、いつから会いたかったんですか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Aww... How romantic! How long have you been longing to see this person again?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "總覺得好浪漫哟～妳從什麼時候開始想要見他的啊？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "โอ๊ย... โรแมนติกจัง! เธอรอพบเขามานานแค่ไหนแล้วนะ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Aww... Thật lãng mạn! Bạn đã khao khát được gặp lại người này bao lâu rồi?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "总觉得很浪漫诶~ 从什么时候开始想要见他的啊？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ooooh … Wie romantisch! Wie lange hast du gesucht, um diesen Menschen wieder zu sehen?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Oooh... Comme c'est romantique ! Depuis combien de temps tu veux revoir cette personne ?"
L46_1.m_Talk_FRA = L47_1
