L50_1 = "R_M_I"
L49_1.m_Pos = L50_1
L50_1 = "난 그런 얘긴 잘 모르겠고, 뭐하는 사람이야? 강해?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そんなことより、何する人なの？　強い？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Yeah, I couldn't care less about that sappy nonsense. Who is this Teacher anyway? Strong?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "我對這方面不太瞭解……他是做什麼的？很強嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เออ ฉันไม่สนเรื่องน้ำเน่าไร้สาระหรอก ว่าแต่คุณครูคนนี้เป็นใครนะ? เก่งมั้ย?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Được rồi, tôi không quan tâm mấy chuyện vớ vẩn đó. Dù sao thì Giáo Viên này là ai vậy? Có mạnh không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "我对那方面不太了解，他从事什么工作啊？很强吗？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Dieser romantische Blödsinn ist mir total egal. Wer ist dieser Lehrer überhaupt? Ist er stark?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Bon, je m'en fiche de vos bêtises sentimentales. C'est qui, ce Professeur ? Il est fort ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
