L50_1.m_Face = "UNIT_PRIDE"
L50_1.m_CharStrID = "GAEUN_HB_NULL_NULL"
L50_1.m_Pos = "L"
L51_1 = "내가 아는 한 제일 강한 사람이야."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "私が知る限り、一番強い人よ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "As far as I know, Teacher is the strongest person there is."
L50_1.m_Talk_ENG = L51_1
L51_1 = "是我認識的人裡面最強的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เท่าที่ฉันรู้ คุณครูคือคนที่แข็งแกร่งที่สุด"
L50_1.m_Talk_THA = L51_1
L51_1 = "Theo như tôi biết, Giáo Viên là người mạnh nhất ở đó."
L50_1.m_Talk_VTN = L51_1
L51_1 = "是我认识的人里最强的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Die stärkste Person, die ich kenne."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Pour moi, le Professeur est la personne la plus forte au monde."
L50_1.m_Talk_FRA = L51_1
