L2_1.m_Pos = "C"
L3_1 = "자, 자. 두 사람, 개인적인 질문은 그만."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "さあ、二人とも。個人的な質問はそこまでよ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Alright, you two. Enough with the personal questions."
L2_1.m_Talk_ENG = L3_1
L3_1 = "好了，好了，妳們兩個，私人問題就到此為止吧。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เอาละ พวกเธอสองคน เลิกถามคำถามส่วนตัวได้แล้ว"
L2_1.m_Talk_THA = L3_1
L3_1 = "Được rồi, hai người. Đâm chọt đời tư như vậy là đủ rồi."
L2_1.m_Talk_VTN = L3_1
L3_1 = "好了好了，你们两个，提问就到此为止吧。"
