L4_1 = "가은 양. 여기 에블린 언니의 특제 초콜릿이야."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ユキさん。これはエヴリンお姉さんの特製チョコレートよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Gaeun. Try my special chocolate here."
L3_1.m_Talk_ENG = L4_1
L4_1 = "嘉恩小姐，這是伊芙琳姐姐的特製巧克力。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "กาอึน ลองช็อกโกแลตสูตรพิเศษของฉันนี่สิ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Gaeun. Hãy thử sô cô la đặc biệt của tôi nhé."
L3_1.m_Talk_VTN = L4_1
L4_1 = "嘉恩小姐，这是伊芙琳姐姐特制的巧克力。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Gaeun. Probier mal meine Spezialschokolade hier."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Gaeun, goûte mon chocolat spécial."
L3_1.m_Talk_FRA = L4_1
