L5_1 = "한입만 먹어도 두려움이 사라진단다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "一口食べるだけで何も恐れなくなるわ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Just one bite will make your fears subside."
L4_1.m_Talk_ENG = L5_1
L5_1 = "吃一口就能消除妳的恐懼。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "กัดคำเดียว ความกลัวก็จะหายไป"
L4_1.m_Talk_THA = L5_1
L5_1 = "Một miếng nhỏ cũng sẽ làm dịu đi nỗi sợ hãi của bạn."
L4_1.m_Talk_VTN = L5_1
L5_1 = "吃一口就能消除你的恐惧。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Mit nur einem Biss sind all deine Ängste vergessen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Une bouchée et toutes tes peurs vont s'envoler."
L4_1.m_Talk_FRA = L5_1
