L6_1 = "고맙습니다. 잘 먹을게요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ありがとうございます。いただきます。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Thank you. You're very kind."
L5_1.m_Talk_ENG = L6_1
L6_1 = "謝謝妳，我會好好享用的。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ขอบคุณค่ะ คุณใจดีจัง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Cảm ơn bạn. Bạn tốt bụng quá."
L5_1.m_Talk_VTN = L6_1
L6_1 = "谢谢你。我会好好享用的。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Danke. Du bist sehr gut zu mir."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Merci. C'est très gentil."
L5_1.m_Talk_FRA = L6_1
