L8_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L7_1.m_StartFXSoundName = L8_1
L7_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "자, 받아. 이건 부끄러움을 잊게 만들어 주는 드레스야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ほら、受け取れ。これは恥じらいを忘れさせるドレスだ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Here, take this. This dress will make your shyness go away."
L7_1.m_Talk_ENG = L8_1
L8_1 = "然後，穿上這個。這是能讓妳忘掉害羞的禮服。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เอา เอานี่ไป ชุดนี้จะทำให้ความขี้อายของเธอหายไป"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đây, cầm lấy cái này. Chiếc váy này sẽ khiến sự ngại ngùng của bạn biến mất."
L7_1.m_Talk_VTN = L8_1
L8_1 = "来，接着。这是能让你不再害羞的礼服。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Hier, nimm auch das. In diesem Kleid verfliegt deine Schüchternheit wie von selbst."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Tiens, prends ça. Cette robe va faire disparaître ta timidité."
L7_1.m_Talk_FRA = L8_1
