L9_1 = "COUNTERCASE_GAEUN_NORMAL_4@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 31354
