L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "솔직하게 네 마음을 말할 수 있어."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "正直に汝の気持ちを言えるだろう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "You'll be able to express feelings honestly."
L8_1.m_Talk_ENG = L9_1
L9_1 = "可以讓妳坦率地說出自己的心聲。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เธอจะได้แสดงความรู้สึกได้อย่างตรงไปตรงมา"
L8_1.m_Talk_THA = L9_1
L9_1 = "Bạn sẽ có thể bày tỏ cảm xúc trung thực."
L8_1.m_Talk_VTN = L9_1
L9_1 = "可以让你坦率地表达出自己的心声。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Du kannst deine Gefühle ehrlich zum Ausdruck bringen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Elle te permettra d'exprimer librement tes sentiments."
L8_1.m_Talk_FRA = L9_1
