L11_1 = "UNIT_SURPRISE"
L10_1.m_Face = L11_1
L10_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "어? 이거 저번에 관리국에서 운 좋게 낙찰 받은 물건 아냐?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あれ？　これって前に管理局で運よく落札した物じゃないの？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Huh? Didn't we get this at an auction from the Administration?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "咦？那不是上次在管理局幸運得標的東西嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "หืม? เาได้ชุดนี้มาจากการประมูลที่องค์การบริหารโลกไม่ใช่เหรอ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Huh? Không phải chúng ta đã nhận được thứ này trong một cuộc đấu giá từ Cục Quản Lý sao?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "哦？那不是上次在管理局拍到的东西吗？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ach? Haben wir das nicht bei einer Auktion der Administration bekommen?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Quoi ? On n'a pas acheté ça à une vente aux enchères de l'Administration ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_GAEUN_NORMAL_4@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31354
L11_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_LAUGH"
L11_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "저주를 걸어서 카페 벌칙용으로 쓰겠다더니......"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "呪いをかけてカフェの罰ゲーム用に使うって言ってなかったっけ……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I thought you were going to put a curse on it and use it to prank terrible customers..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "說是下了詛咒，要當作咖啡廳裡的懲罰用道具……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "นึกว่าเธอลงคำสาปไว้และเอาไว้แกล้งลูกค้าแย่ๆ ซะอีก..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi tưởng bạn đã đặt một lời nguyền vào nó và sử dụng nó để chơi khăm những khách hàng khó chịu của chúng ta..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "说是下了诅咒要在咖啡厅做惩罚用道具的……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wolltest du das nicht mit einem Fluch belegen, um nervige Kunden …"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je croyais que tu voulais la maudire et t'en servir pour jouer des tours aux mauvais clients..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "COUNTERCASE_GAEUN_NORMAL_4@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 31354
L12_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
