L13_1 = "UNIT_SERIOUS"
L12_1.m_Face = L13_1
L12_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Crash = 30
L13_1 = "시, 시끄러워! 저주건 뭐건 목표만 달성하면 되잖아!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "う、うるさい！　呪いも何も、目標さえ達成すればいいだろ！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Sh-shut up! Who cares what it was originally for, as long as it gets the job done!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "吵，吵死了！管它詛咒不詛咒的，只要能達成目的不就行了！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "หะ-หุบปากน่า! ใครจะไปสนว่าเดิมมันมีไว้ทำอะไร ตราบใดที่มันทำให้งานเสร็จ!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Im đi! Ai quan tâm tác dụng ban đầu cơ chứ, miễn là nó hoàn thành công việc!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "吵，吵死了！管它诅咒不诅咒的，只要能达成目标不就行了！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "K-Klappe! Ist doch egal, wofür es mal gedacht war. Hauptsache, es tut seinen Zweck."
L12_1.m_Talk_DEU = L13_1
L13_1 = "H-Hé, tais-toi ! On s'en fiche de ce qu'elle devait faire à la base, tant qu'elle marche !"
L12_1.m_Talk_FRA = L13_1
