L14_1.m_Crash = 20
L15_1 = "부끄러운 의상...... 하지만 선생님을 위해서라면......"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "恥ずかしい衣装……でも先生のためなら……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "This seems a bit gaudy... But if it's for Teacher..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "好令人害羞的衣服……但如果是為了老師的話……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ดูฉูดฉาดไปหน่อยนะคะ... แต่ก็เพื่อคุณครู..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Thứ này có vẻ hơi lòe loẹt... Nhưng nếu là vì Giáo Viên..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "这衣服，有点害羞……但是为了老师……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Das wirkt etwas auffällig … Aber es ist ja für den Lehrer …"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Elle est un peu tape-à-l'œil... Mais si c'est pour le Professeur..."
L14_1.m_Talk_FRA = L15_1
