L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 31354
L17_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
