L17_1.m_Pos = "R"
L18_1 = "자, 이제 됐지? 또 괜한 손님 오기 전에 얼른 가게 문 닫을 준비 하자."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "さ、もういいな？　また変な客が来る前に閉店の準備をしよう。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "There. Satisfied? Now let's close shop before we get another customer."
L17_1.m_Talk_ENG = L18_1
L18_1 = "現在可以了吧？那在其他多餘的客人上門之前，趕快準備打烊吧。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "นี่ไง พอใจรึยัง? ทีนี้ก็ปิดร้านก่อนที่จะมีลูกค้าเข้ามาอีก"
L17_1.m_Talk_THA = L18_1
L18_1 = "Đây. Hài lòng rồi chứ? Bây giờ chúng ta hãy đóng cửa tiệm trước khi có một khách hàng khác."
L17_1.m_Talk_VTN = L18_1
L18_1 = "现在行了吧？那赶紧去把门关上吧，免得又来客人了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Gut. Zufrieden? Lass uns zumachen, bevor noch mehr Kundschaft kommt."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Voilà. Contente ? Maintenant fermons avant qu'un autre client arrive."
L17_1.m_Talk_FRA = L18_1
