L19_1 = "COUNTERCASE_GAEUN_NORMAL_4@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 31354
L18_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L18_1.m_Pos = "L"
L19_1 = "후훗. 모처럼 마녀다운 일이잖아. 자랑스러워해도 될 텐데."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ふふっ。せっかく魔女らしいことをしたんだから。誇らしく思ってもいいのに。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Heh heh. But this is what witches are supposed to do. I think you can take a little more pride in this."
L18_1.m_Talk_ENG = L19_1
L19_1 = "呵呵，難得做了件魔女的本職工作呢，妳可以感到驕傲喔。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "หึหึ แต่นี่คือสิ่งที่แม่มดควรทำนะ ฉันว่าเธอควรจะภูมิใจในงานนี้ให้มากกว่านี้อีกหน่อย"
L18_1.m_Talk_THA = L19_1
L19_1 = "Hơ hơ. Nhưng đây là những chuyện mà một phù thủy phải làm. Tôi nghĩ bạn có thể tự hào hơn một chút đấy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "哈哈，难得干件了魔女的本职工作啊，你可以自豪一下哦。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Hehe, aber genau das ist es, was Hexen tun sollen. Ich finde, du kannst ruhig etwas stolzer darauf sein."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Hé hé. Mais c'est à ça que servent les sorcières. Tu devrais en être un peu plus fière."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
