L22_1 = "COUNTERCASE_GAEUN_NORMAL_4@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 31354
L21_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L22_1 = "R_M_I"
L21_1.m_Pos = L22_1
L22_1 = "저기, 기왕 갈아입는 김에 이 구두는 어때?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "君、着替えるついでにこの靴はどう？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Hey, if you're going to change your clothes anyway, why don't you try on these shoes?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "那個，脫都脫了，要不要順便再換雙鞋？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "นี่ ถ้าไหนๆ ก็จะเปลี่ยนชุดแล้ว ทำไมไม่ลองสวมรองเท้าพวกนี้ล่ะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Này, nếu bạn định thay quần áo, sao bạn không thử đôi giày này nhỉ?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "那个，脱都脱了，要不要顺便再换双鞋？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Hey, wenn du dich sowieso umziehst, probier doch noch diese Schuhe an."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hé, puisque tu vas changer de tenue, tu ne veux pas essayer ces chaussures aussi ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "COUNTERCASE_GAEUN_NORMAL_4@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 31354
L22_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L22_1.m_Pos = "R"
L23_1 = "창고에서 가져 온 거지만 꽤 새것 같다구? 잘 어울릴 것 같은데?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "倉庫から持ってきたんだけど、新品に見えるでしょ？　よく似合いそうだけど？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I dug them up from the storage, but they're as good as new! I bet they'll go well with your outfit."
L22_1.m_Talk_ENG = L23_1
L23_1 = "雖然是在倉庫裡拿的，但看起來還很新吧？應該很適合妳喔？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันขุดขึ้นมาจากที่เก็บของ แต่มันยังดีเหมือนใหม่เลยนะ! มันจะต้องเข้ากับชุดแน่ๆ!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi đã đào chúng lên từ kho lưu trữ đấy, nhưng chúng vẫn tốt như mới! Tôi cá là chúng sẽ rất hợp với trang phục của bạn."
L22_1.m_Talk_VTN = L23_1
L23_1 = "虽说是在仓库里拿的，但看起来很新吧？应该很适合你？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich habe sie im Lager gefunden, aber die sind so gut wie neu! Ich wette, die passen super zu deinem Outfit."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Je les ai trouvées dans la réserve, mais elles sont comme neuves ! Je parie qu'elles iront bien avec ta tenue."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "COUNTERCASE_GAEUN_NORMAL_4@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 31354
L23_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "GAEUN_HB_NULL_NULL"
L23_1.m_Pos = "L"
L24_1 = "고마워. 신으니까 어쩐지 가슴이 두근거려."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ありがとう。履いたらなんだか胸がドキドキしてきた。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I appreciate it. Somehow it's making my heart all fluttery."
L23_1.m_Talk_ENG = L24_1
L24_1 = "謝謝……穿上後總覺得心臟跳得好快喔。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ขอบคุณนะคะ ไม่รู้ทำไมมันทำให้หัวใจฉันเต้นรัว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Rất cảm kích. Nó khiến trái tim tôi rung động."
L23_1.m_Talk_VTN = L24_1
L24_1 = "谢谢。我穿上了，有没有种怦然心动的感觉？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Danke. Irgendwie wird mir da ganz warm ums Herz."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je suis touchée. J'en ai le cœur qui palpite."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
