L26_1 = "COUNTERCASE_GAEUN_NORMAL_4@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31354
L25_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
