L25_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L26_1 = "R_M_I"
L25_1.m_Pos = L26_1
L26_1 = "앗, 그럼 나도! 저번에 청소하다 찾은 티아라인데 잘 어울릴 거 같아요!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あっ、じゃあ私も！　この前掃除中に見つけたティアラですが、これもよく似合いそうです！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Oh, then I've got one too! I found this tiara while cleaning the other day. I think it'll look perfect on you!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "啊，那我也來！這是我上次打掃時找到的頭飾，肯定也很適合妳！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "อ๊ะ งั้นฉันก็มีเหมือนกัน! ฉันเจอเทียร่าอันนี้ตอนทำความสะอาดเมื่อวันก่อน ฉันว่ามันจะเข้ากับเธอมากนะ!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Ồ, vậy thì tôi cũng có một thứ đây! Tôi đã tìm thấy vương miện này trong khi dọn dẹp. Tôi nghĩ nó sẽ giúp bạn trông hoàn hảo hơn!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "啊，那我也来！这是我上次清扫时找到的头饰，肯定也特别合适！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Oh, dann habe ich auch etwas für dich. Diese Tiara habe ich vor Kurzem beim Aufräumen gefunden. Ich wette, die steht dir fantastisch."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Oh, alors j'ai quelque chose, moi aussi ! J'ai trouvé cette tiare en faisant le ménage l'autre jour. Je pense qu'elle t'ira à ravir !"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
