L27_1 = "고마워. 쓰니까 어쩐지 머리가......"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ありがとう。つけたらなぜか頭が……"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Thanks. It's making my head feel..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "謝謝……戴上了總覺得頭有點暈……"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ขอบคุณค่ะ มันทำให้หัวฉันรู้สึก..."
L26_1.m_Talk_THA = L27_1
L27_1 = "Cảm ơn. Nó khiến đầu tôi cảm thấy..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "谢谢。带上了总觉得头有点晕……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Danke. Damit fühle ich mich …"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Merci. Ma tête est..."
L26_1.m_Talk_FRA = L27_1
