L32_1 = "COUNTERCASE_GAEUN_NORMAL_4@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 31354
L31_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_PRIDE"
L32_1 = "GAEUN_HB_VAL_BLACK"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "그럼요. 막 들뜨고 가슴이 울렁거리는 게 그 어느 때보다 괜찮은 것 같아요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ええ。心が浮き立って胸がざわつくのが、いつにも増して気持ちがいいです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Of course. My heart is racing like crazy but I feel better than ever."
L31_1.m_Talk_ENG = L32_1
L32_1 = "當然了。沒有比這種興奮又心跳不已的感覺更好了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "สบายดีค่ะ หัวใจเต้นเร็วเป็นบ้า แต่รู้สึกดีที่สุดเลย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tất nhiên. Tim tôi đập loạn xạ, nhưng tôi cảm thấy dễ chịu hơn bao giờ hết."
L31_1.m_Talk_VTN = L32_1
L32_1 = "当然了。这种兴奋激动的心情，感觉状态比任何时候都要好。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Oh ja. Mein Herz rast, aber mir ging es nie besser."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Bien sûr. Mon cœur bat la chamade mais je ne me suis jamais sentie aussi bien."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "COUNTERCASE_GAEUN_NORMAL_4@82#Talk"
