L32_1.m_Crash = 25
L33_1 = "다행이다~ 또 실수해 버렸나 했는데~"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "よかった～また失敗したと思った～。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Phew, thank goodness. I thought I messed up again."
L32_1.m_Talk_ENG = L33_1
L33_1 = "好險～我還以為又搞砸了呢～"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เอ้อ ค่อยยังชั่ว นึกว่าจะทำพลาดอีกแล้ว"
L32_1.m_Talk_THA = L33_1
L33_1 = "Phù, cảm ơn trời đất. Tôi cứ tưởng mình lại làm rối tung mọi chuyện nữa cơ chứ."
L32_1.m_Talk_VTN = L33_1
L33_1 = "好险~我还以为又搞砸了呢~"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Puh, Gott sei Dank. Ich dachte schon, ich hätte wieder etwas falsch gemacht."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ouf, ça me rassure. J'ai cru que j'avais encore fait une bêtise."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_GAEUN_NORMAL_4@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31354
L33_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "GAEUN_HB_VAL_BLACK"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "고마워요, 다들. 선생님을 향한 제 사랑을 응원해 줘서."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ありがとう、みんな。先生への私の愛を応援してくれて。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Thank you, everyone. Thanks for cheering on my love for Teacher."
L33_1.m_Talk_ENG = L34_1
L34_1 = "謝謝大家，謝謝大家支持我對老師的愛。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ขอบคุณค่ะทุกคน ขอบคุณที่เอาใจช่วยความรักที่ฉันมีต่อคุณครูนะคะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cảm ơn mọi người. Cảm ơn vì đã cổ vũ tình yêu của tôi dành cho Giáo Viên."
L33_1.m_Talk_VTN = L34_1
L34_1 = "谢谢大家。谢谢大家声援我对老师的爱。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Euch allen vielen Dank. Danke, dass ihr meine Liebe für meinen Lehrer akzeptiert."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Merci à toutes. Merci d'avoir encouragé mon amour pour le Professeur."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_GAEUN_NORMAL_4@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31354
L34_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_DESPAIR"
L35_1 = "GAEUN_HB_VAL_BLACK"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "선생님께서도...... 제가 찾아오기만을 애타게 기다리고 계시겠죠."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "先生もきっと……私が訪ねてくることを心待ちにしていることでしょう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I'm sure... Teacher's longing for me to come back."
L34_1.m_Talk_ENG = L35_1
L35_1 = "老師也……肯定正焦急地等待我的到來吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฉันมั่นใจ... ว่าคุณครูก็อยากให้ฉันกลับไป"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi chắc rằng... Giáo Viên đang mong mỏi tôi trở lại."
L34_1.m_Talk_VTN = L35_1
L35_1 = "老师也……肯定在焦急等待我的到来吧。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Bestimmt … sehnt sich mein Lehrer danach, dass ich zurückkomme."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je suis sûre que... le Professeur veut que je revienne."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
