L35_1.m_Crash = 30
L36_1 = "베리베리 큐♥ 가은, 오늘 방송은 선생님과 초코처럼 달콤한 사랑 나누기랍니다♥"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ベリーベリー。キュー♥　ユキ、今日の放送は先生とチョコのように甘い愛の分かち合いです♥"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Berry Berry Cue! ♥ This is Gaeun! Today's episode will be on my chocolate sweet romance with my Teacher! ♥"
L35_1.m_Talk_ENG = L36_1
L36_1 = "莓果莓果～♥嘉恩，今天的直播是分享我和老師之間，像巧克力一樣甜蜜的愛情哟♥"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เบอร์รี่ เบอร์รี่ คิว! ♥ กาอึนเองค่ะ! วันนี้จะเป็นเรื่องของความรักแสนหวานปานช็อกโกแลตของฉันกับคุณครู! ♥"
L35_1.m_Talk_THA = L36_1
L36_1 = "Berry Berry Cue! ♥ Đây là Gaeun! Tập hôm nay sẽ nói về tình cảm lãng mạn ngọt ngào như sô cô la đối với Giáo Viên của tôi! ♥"
L35_1.m_Talk_VTN = L36_1
L36_1 = "莓果莓果~♥嘉恩，今天的节目是分享我与老师巧克力一样甜蜜的爱情♥"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Berry Berry Cue! ♥ Hier ist Gaeun! In der heutigen Folge geht es um meine zuckersüße Romanze mit meinem Lehrer! ♥"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Vive Berry ! ♥ Ici Gaeun ! L'épisode d'aujourd'hui sera consacré à ma douce romance sucrée avec le Professeur ! ♥"
L35_1.m_Talk_FRA = L36_1
