L40_1 = "......방금 뭐야? 쟤 맛이 갔는데?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "……おい、さっきの何だ？　正気じゃないぞ？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "What the heck was that? She's completely bonkers!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "……剛剛那是什麼？那孩子好像變了個人一樣？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "นั่นอะไรน่ะ? เธอบ้าไปแล้ว!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cái quái gì vậy? Cô ấy hoàn toàn hưng phấn!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "……刚刚那是什么？不太对啊？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Was zum Teufel war das? Sie dreht komplett durch!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "C'est quoi ce délire ? Elle est devenue dingue !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_GAEUN_NORMAL_4@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 31354
L40_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
