L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L40_1.m_Pos = "R"
L41_1 = "유나, 잉그리드. 두 사람 방금 저 손님에게 뭐 주지 않았어?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ユナ、イングリッド。二人ともさっき、あのお客さんに何か渡さなかった？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Yuna, Ingrid. Didn't you two just give her something?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "尤娜，英格麗，妳們兩個是不是給了那位客人什麼東西？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ยูนา อิงกริด พวกเธอสองคนเอาอะไรให้เธอน่ะ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Yuna, Ingrid. Không phải hai người vừa đưa cho cô ấy thứ gì đấy chứ?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "尤娜，英格丽，你们两个刚才是不是给那位客人什么东西了？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Yuna, Ingrid. Habt ihr beiden ihr nicht gerade etwas gegeben?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Yuna, Ingrid. Vous lui avez donné quelque chose ?"
L40_1.m_Talk_FRA = L41_1
