L43_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L43_1.m_Pos = "L"
L43_1.m_Crash = 25
L44_1 = "앗, 그게 창고에서 찾은 티아라가 예뻐 보여서......"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あっ、それが倉庫で見つけたティアラが綺麗だったから……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Oh, I thought the tiara I found in the storage was pretty..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "啊，我只是覺得倉庫裡找到的頭飾很漂亮……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "อ๋อ ฉันคิดว่าเทียร่าที่เจอในที่เก็บของมันสวยดี..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Ồ, tôi nghĩ chiếc vương miện mà tôi tìm thấy trong kho lưu trữ rất đẹp..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "啊，只是觉得仓库里找到的头饰看起来很漂亮……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Oh, ich dachte, diese Tiara, die ich im Lager gefunden habe, wäre recht schön …"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Oh, je trouvais que la tiare que j'ai trouvée était jolie..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "COUNTERCASE_GAEUN_NORMAL_4@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31354
L44_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L44_1.m_Pos = "R"
L44_1.m_Crash = 20
L45_1 = "나, 나도 그냥 잘 어울릴 것 같아서 창고에 있던 구두만 줬을 뿐이라구."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "わ、私もよく似合いそうだと思って、倉庫にあった靴を渡しただけよ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "A-and I just thought those shoes from the storage would look great on her as well."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我、我也只是覺得那雙鞋會很適合那位客人，所以才給她的啊。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "สะ-ส่วนฉันก็คิดว่ารองเท้าจากที่เก็บของดูเข้ากับเธอเหมือนกัน"
L44_1.m_Talk_THA = L45_1
L45_1 = "V-và tôi chỉ nghĩ rằng đôi giày từ kho lưu trữ sẽ trông rất tuyệt đối với cô ấy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "我，我也只是感觉那双鞋会很适合客人所以才给她的啊。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "U-und ich dachte, dass ihr die Schuhe aus dem Lager super stehen würden."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Et je me disais que les chaussures de la réserve lui iraient bien."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
