L46_1.m_Face = "UNIT_DESPAIR"
L46_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "잡념을 잊게 만드는 티아라에 기분을 고양시키는 구두네."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "雑念を忘れさせるティアラに、気分を高揚させる靴だな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "That tiara makes you forget about any distractions, while the shoes uplift your mood."
L46_1.m_Talk_ENG = L47_1
L47_1 = "能消除雜念的頭飾，加上能讓人情緒高漲的鞋子。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เทียร่านั้นทำให้เราลืมสิ่งกวนใจ ส่วนรองเท้าจะทำให้อารมณ์ดี"
L46_1.m_Talk_THA = L47_1
L47_1 = "Vương miện đó khiến bạn quên đi mọi phiền muộn, trong khi đôi giày nâng cao tâm trạng."
L46_1.m_Talk_VTN = L47_1
L47_1 = "能消除杂念的头饰加上能让人情绪高涨的皮鞋。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Mit der Tiara kann die Trägerin nichts mehr ablenken und die Schuhe versetzen sie in einen Zustand der Glückseligkeit."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Cette tiare fait oublier les distractions, et les chaussures améliorent l'humeur."
L46_1.m_Talk_FRA = L47_1
