L51_1 = "아야야야! 플루토, 그만해! 두 개! 정어리 두 개!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "イタタタ！　プルートー、やめて！　二つ！　イワシ二つあげるから！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Ow! Pluto, stop it! I'll give you two! Two cans of tuna!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "呀啊啊啊！布魯托，STOP！兩罐！兩罐沙丁魚！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "โอ๊ย! พลูโต หยุดนะ! เดี๋ยวให้สองเลย! ทูน่าสองกระป๋อง!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ôi! Pluto, dừng lại! Tôi sẽ cho bạn hai lon! Hai lon cá ngừ!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "啊啊啊啊！够了，布鲁托！两罐！两罐沙丁鱼！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Au! Aus, Pluto! Ich geb dir zwei, zwei Dosen Thunfisch!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Aïe ! Pluto, arrête ! Je te donnerai deux boîtes de thon ! Deux !"
L50_1.m_Talk_FRA = L51_1
