L2_1 = "COUNTERCASE_GAEUN_NORMAL_4@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 31354
