L2_1 = "UNIT_IDLE"
L1_1.m_Face = L2_1
L1_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L1_1.m_Pos = "L"
L2_1 = "자기 마음에 솔직해지고, 두려움도 모르는 상태인 데다가 잡념까지 사라졌어."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "自分の気持ちに素直になって、恐れも知らないうえに雑念まで消えた。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "She's become honest about her feelings and fearless. And now all her distractions are gone."
L1_1.m_Talk_ENG = L2_1
L2_1 = "內心變得坦率，然後在無所畏懼的狀態下，連雜念都消失了。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เธอจะซื่อสัตย์ต่อความรู้สึกของตัวเองและไม่กลัวอะไร ตอนนี้เรื่องกังวลใจของเธอหายไปแล้ว"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cô ấy trở nên trung thực về cảm xúc của mình và không còn sợ hãi. Bây giờ tất cả những phiền muộn của cô ấy đã biến mất."
L1_1.m_Talk_VTN = L2_1
L2_1 = "消除杂念忘记恐惧的同时，对自己的内心坦率。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Sie gesteht sich ihre Gefühle offen ein und kennt keine Furcht oder Ablenkung mehr."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Elle exprime ouvertement ses sentiments et elle n'a plus peur de rien. Et maintenant, rien ne peut la distraire."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "COUNTERCASE_GAEUN_NORMAL_4@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 31354
L2_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L2_1.m_Pos = "L"
L3_1 = "그 상태로 기분이 들뜨면 사람이 어떻게 되는 줄 알아?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "その状態で気分まで高揚したら人がどうなるのかわかるか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You know what happens when you boost someone's mood on top of all that?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "如果在這種情況下情緒高漲，妳們知道會發生什麼事情嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "พวกเธอก็รู้ว่าจะเกิดอะไรขึ้นเวลาที่เรายกระดับอารมณ์ใครสักคนแบบนั้น?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Bạn biết điều gì sẽ xảy ra khi tâm trạng của một người được nâng lên mức cao nhất không?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "如果这种情况下情绪高涨，你们知道会发生什么吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Was glaubt ihr passiert, wenn ihr so jemanden dann noch in Euphorie versetzt?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Vous savez ce qui arrive quand on améliore l'humeur de quelqu'un en plus de ça ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
