L5_1.m_Pos = "C"
L6_1 = "눈에 뵈는 게 없어져."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "我を忘れてしまうんだ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "She becomes unstoppable."
L5_1.m_Talk_ENG = L6_1
L6_1 = "她的眼睛會看不見任何東西。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เธอจะหยุดไม่อยู่ไง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không ai có thể ngăn cản được cô ấy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "她看不顺的事物都会被消灭。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Sie wird unaufhaltsam."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Rien ne peut plus l'arrêter."
L5_1.m_Talk_FRA = L6_1
