L11_1 = "COUNTERCASE_GAEUN_NORMAL_4@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 31354
L10_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_PRIDE"
L10_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L10_1.m_Pos = "L"
L11_1 = "뭐, 효력은 길어 봐야 30분도 안 되려나. 큰 사고만 안 나면 좋겠는데."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "まあ、効果は長くて30分くらいだがな。大事に至らなきゃいいのだが。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Well, I guess the spell will last no more than half an hour. Hopefully it won't end up in disaster."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不過嘛，效果再長也只會持續30分鐘，不要出什麼大事就好了。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ฉันว่าคาถาจะทำงานได้ไม่เกินครึ่งชั่วโมงหรอก หวังว่าจะไม่เกิหายนะขึ้นนะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Chà, tôi đoán câu thần chú sẽ kéo dài không quá nửa giờ. Hy vọng rằng chuyện này sẽ không kết thúc trong thảm họa."
L10_1.m_Talk_VTN = L11_1
L11_1 = "不过效果再长也只会持续30分钟，只要别出什么大事儿就行。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Also ich schätze, der Spruch hält nicht mehr als eine halbe Stunde an. Hoffentlich endet all das nicht in einer Katastrophe."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Bon, je pense que le sort ne va pas durer plus d'une demi-heure. Espérons que ça ne se finira pas en désastre."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_GAEUN_NORMAL_4@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31354
L11_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_DESPAIR"
L11_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L11_1.m_Pos = "R"
L12_1 = "그래? 지금이라도 뺏어 와야 할까?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "そうなの？　今からでも取り返したほうがいい？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Really? Should we go get the items back before it's too late?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "是嗎？我們現在不用去把東西搶回來嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "จริงเหรอ? ฉันว่าเราควรเอาของคืนก่อนจะสายเกินไปรึเปล่า?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Thật ư? Chúng ta có nên đi lấy lại đồ trước khi quá muộn không?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "嗯？是不是现在该去抢回来？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Echt? Sollen wir die Sachen zurückholen, bevor es zu spät ist?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Vraiment ? Il ne vaudrait pas mieux qu'on aille récupérer ces objets avant qu'il ne soit trop tard ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "COUNTERCASE_GAEUN_NORMAL_4@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 31354
L12_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L12_1.m_Pos = "L"
L13_1 = "뭐...... 카운터였잖아. 몸살 좀 앓는 정도로 끝날 거야. 그리 걱정할 거 없어."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "まあ……カウンターだからな。少し体調を崩すくらいで済むだろう。そんなに心配することはない。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Well... She's a Counter. She'll just feel a little sick afterwards, that's all. Nothing to worry about."
L12_1.m_Talk_ENG = L13_1
L13_1 = "這個嘛……她不是制裁者嗎？他只會稍微感到疲憊，然後就結束了吧，不需要那麼擔心。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ก็... เธอเป็นเคาน์เตอร์นะ หลังจากนี้เธอจะแค่รู้สึกพะอืดพะอม ไม่มีอะไรต้องเป็นห่วง"
L12_1.m_Talk_THA = L13_1
L13_1 = "Chà... Cô ấy là một Counter. Cô ấy sẽ chỉ cảm thấy hơi mệt mỏi sau vụ này, chỉ vậy thôi. Không có gì phải lo lắng đâu."
L12_1.m_Talk_VTN = L13_1
L13_1 = "什么……再怎么说她也是制裁者，应该只是会稍稍有些异样，很快就会结束了吧，不用那么担心。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Nun … Sie ist ein Counter. Sie wird höchstens ein bisschen Kopfschmerzen haben. Kein Grund, sich Sorgen zu machen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Eh bien... C'est une Compteuse. Elle va sans doute se sentir un peu malade après coup. Rien d'inquiétant."
L12_1.m_Talk_FRA = L13_1
