L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 31354
L14_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
