L15_1 = "UNIT_IDLE"
L14_1.m_Face = L15_1
L14_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L14_1.m_Pos = "R"
L15_1 = "아니, 그 선생님이란 사람 말이야."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "いや、心配なのはその先生って人のことよ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I'm more worried about that Teacher she was talking about."
L14_1.m_Talk_ENG = L15_1
L15_1 = "不，我是擔心那位老師。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ฉันเป็นห่วงเรื่องคุณครูที่เธอพูดถึงมากกว่า"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi lo lắng cho vị Giáo Viên mà cô ấy vừa nói đến hơn."
L14_1.m_Talk_VTN = L15_1
L15_1 = "不，我是担心那位老师。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich mache mir um diesen „Lehrer“ ehrlich gesagt mehr Sorgen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Je m'inquiète plutôt pour ce Professeur dont elle parlait."
L14_1.m_Talk_FRA = L15_1
