L16_1 = "COUNTERCASE_GAEUN_NORMAL_4@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 31354
L15_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_LAUGH"
L15_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L15_1.m_Pos = "R"
L16_1 = "마법이 풀리기 전까지 버틸 수 있으려나 모르겠네. 후훗."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "魔法が解けるまで耐えられるかわからないわね。ふふっ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I wonder if this person will manage to last until the spell wears off. Heh heh."
L15_1.m_Talk_ENG = L16_1
L16_1 = "不知道他能不能撐到魔法失效為止呢，呵呵。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "อยากรู้ว่าคนคนนี้จะอยู่ได้นานพอที่คาถาจะหมดฤทธิ์มั้ย หึๆ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi tự hỏi liệu người này có thể sống sót cho đến khi câu thần chú hết tác dụng không. Hơ hơ."
L15_1.m_Talk_VTN = L16_1
L16_1 = "不知道能不能撑到魔法失效为止，呵呵。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich frage mich, ob diese mysteriöse Person übersteht, bis der Spruch seine Wirkung verliert. Hehe."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Je me demande s'il va tenir le coup jusqu'à ce que le sort se dissipe. Hé hé."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
