L19_1 = "m_bCharHologramEffect"
L18_1[L19_1] = true
L19_1 = "며칠 전 일은 하나 씨에게 보고 받았습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "数日前のことはスズカさんに報告を受けました。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Hana briefed me about what happened a few days ago."
L18_1.m_Talk_ENG = L19_1
L19_1 = "前幾天的事情，我已經收到金荷娜小姐的報告了。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ฮานาสรุปให้ฉันฟังว่าเกิดอะไรขึ้นเมื่อไม่กี่วันก่อน"
L18_1.m_Talk_THA = L19_1
L19_1 = "Hana đã kể cho tôi nghe những chuyện đã xảy ra vài ngày trước."
L18_1.m_Talk_VTN = L19_1
L19_1 = "我已经从千叶小姐那边收到了前几天的报告。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Hana hat mir berichtet, was vor ein paar Tagen geschehen ist."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Hana m'a raconté ce qu'il s'est passé il y a quelques jours."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "COUNTERCASE_GAEUN_NORMAL_4@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 31354
L19_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "방송인과도 알고 계시다니 발이 참 넓으시네요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "ストリーマーとも知り合いだなんて、顔が広いようですね。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "You sure get around a lot, getting in touch with people in the entertainment industry too."
L19_1.m_Talk_ENG = L20_1
L20_1 = "沒想到您竟然連直播主都認識，人脈真廣呢。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "คุณไปมาหลายที่นะคะ ติดต่อกับคนในอุตสาหกรรมบันเทิงด้วย"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ngài làm được nhiều chuyện ghê nhỉ, liên lạc với những người trong ngành giải trí luôn cơ đấy."
L19_1.m_Talk_VTN = L20_1
L20_1 = "没想到您的交际面这么广，连主播也认识。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wenn Sie viel umherreisen, kennen Sie doch sicher auch Leute in der Unterhaltungsbranche, oder?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Vous allez vraiment partout, pour connaître des gens jusque dans l'industrie du divertissement."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "COUNTERCASE_GAEUN_NORMAL_4@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 31354
L20_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "다음에는 누군가요? 그림자?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "次は誰ですか？　シャドウ？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "So what next? A shadow?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "下一個是誰？暗影？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "จากนี้อะไรต่อ? แชโดว์เหรอ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Vậy tiếp theo là gì? Cái bóng à?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "下一个是谁？暗影？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Was kommt als Nächstes? Ein Schatten?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Quelle est la prochaine étape ? Une ombre ?"
L20_1.m_Talk_FRA = L21_1
