L23_1 = "COUNTERCASE_GAEUN_NORMAL_4@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 31354
L22_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "ADMIN_COFFIN_NULL_QM"
L22_1.m_CharStrID = L23_1
L23_1 = "농담 말게. 나도 꽤 당황스러웠어."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "冗談じゃない。私もかなり驚いたんだ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Don't even joke about it. It was all very startling for me too."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不要開玩笑了，我也很尷尬啊。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "อย่าล้อเล่นเรื่องนี้สิ ผมเองก็ตกใจมากเหมือนกัน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Đừng đùa về chuyện đó nữa. Tôi cũng rất ngạc nhiên đấy."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不要开玩笑了，我现在也很慌张的。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ach, lassen Sie das. Für mich war das auch alles sehr verwirrend."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ne plaisantez pas à ce sujet. J'ai aussi été très surpris."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "COUNTERCASE_GAEUN_NORMAL_4@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 31354
L23_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "ADMIN_COFFIN_NULL_QM"
L23_1.m_CharStrID = L24_1
L24_1 = "지원금 좀 받아 보려고 시작한 방송 협찬 건이 이런 식으로 틀어질 수가 있나......"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "補助金目当てに放送のスポンサーを引き受けたのに、こんな形でこじれるとは……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I was just trying to get some sponsors on board... I never knew things would go awry like that."
L23_1.m_Talk_ENG = L24_1
L24_1 = "當初我也只是為了拿點支援金，才開始贊助直播的，為什麼事情會變成這樣……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ผมแค่พยายามให้สปอนเซอร์ได้ออกรายการ... ไม่คิดว่าสถานการณ์จะเลวร้ายแบบนั้น"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi chỉ đang cố gắng mời các nhà tài trợ tham gia... Tôi không biết mọi chuyện sẽ trở nên xấu đi như thế."
L23_1.m_Talk_VTN = L24_1
L24_1 = "当初我也只是为了拿点支援金才开始赞助广播的，为什么会落到现在这种地步……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich habe nur versucht, einige Sponsoren zu gewinnen. Ich konnte ja nicht ahnen, dass die Sache so verlaufen würde."
L23_1.m_Talk_DEU = L24_1
L24_1 = "J'essayais simplement de recruter des sponsors... Je ne pensais pas que les choses tourneraient de cette manière."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "COUNTERCASE_GAEUN_NORMAL_4@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 31354
L24_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_IDLE"
L24_1.m_Face = L25_1
L25_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "슬슬 본모습으로 활동하시라는 하늘의 계시 아닐까요?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そろそろ元の姿で活動しなさいという天の啓示ではないでしょうか？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Maybe it's a sign that you should just unveil who you really are again?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "這該不會是要您現出真身，來自上天的啟示吧？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "นี่อาจเป็นสัญญาณว่าคุณควรเผยตัวตนของคุณอีกครั้งนะคะ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Có lẽ đó là một dấu hiệu cho thấy ngài nên tiết lộ lại con người thật của mình?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "是时候以真身出现了吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Vielleicht ist das ein Zeichen, dass Sie Ihre wahre Identität wieder offenbaren sollten?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "C'est peut-être un signe qu'il est à nouveau temps de révéler votre identité au monde ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "COUNTERCASE_GAEUN_NORMAL_4@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31354
L25_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "그래도 감이 좋은 아이네요. 변조음을 잔뜩 넣은 목소리를 듣고 알아차리다니."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "でも勘が良い子なんですね。エフェクトで変調された声に気付くなんて。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Anyway, she's a pretty sharp kid. She recognized your voice even with all the modulation."
L25_1.m_Talk_ENG = L26_1
L26_1 = "不過那孩子的直覺真準呢，居然能透過變調的聲音認出您。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เธอเป็นเด็กที่ฉลาดน่าดู เธอจำเสียงคุณได้ทั้งที่พูดผ่านเครื่องแปลงเสียง"
L25_1.m_Talk_THA = L26_1
L26_1 = "Dù gì thì cô ta cũng là một đứa trẻ khá nhạy bén đấy. Nhận ra giọng nói của ngài ngay cả với tất cả các hiệu ứng đó."
L25_1.m_Talk_VTN = L26_1
L26_1 = "但她的直觉还是一如既往地准呢，居然能通过变调的声音听出是您。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wie auch immer, sie ist ziemlich clever. Sie hat trotz all der Stimmverfremdung Ihre Stimme erkannt."
L25_1.m_Talk_DEU = L26_1
L26_1 = "En tout cas, cette petite est maline. Elle a reconnu votre voix malgré les modulateurs."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31354
L26_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L26_1.m_bWaitClick = false
L26_1.m_fWaitTime = 0
