L28_1 = "COUNTERCASE_GAEUN_NORMAL_4@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31354
L27_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ADMIN_COFFIN_NULL_QM"
L27_1.m_CharStrID = L28_1
L28_1 = "어릴 적에는 앞을 제대로 못 보는 대신에 청각이나 촉감이 굉장히 좋았으니까."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "幼い頃は前がよく見えなかったからな。その代わり聴覚や触覚がかなり鋭かったんだ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Her sense of hearing and touch were very well developed when her sight was limited during her childhood."
L27_1.m_Talk_ENG = L28_1
L28_1 = "因為她小時候視力不好，相對的，聽覺和觸覺就很敏銳。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ทักษะการได้ยินและการสัมผัสของเธอพัฒนาขึ้นตอนที่สายตาเธอไม่ค่อยดีสมัยเด็กๆ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Thính giác và xúc giác của con bé đã phát triển rất tốt, vì thị giác bị hạn chế trong thời thơ ấu."
L27_1.m_Talk_VTN = L28_1
L28_1 = "肯定是因为小时候视力不好，所以听觉和触觉得到了强化吧。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ja, ihre anderen Sinne sind sehr gut entwickelt, weil sie in ihrer Kindheit nicht sehen konnte."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Son sens de l'ouïe et du toucher étaient très développés à l'époque où sa vue était limitée, quand elle était enfant."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_GAEUN_NORMAL_4@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 31354
L28_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "ADMIN_COFFIN_NULL_QM"
L28_1.m_CharStrID = L29_1
L29_1 = "그래도 한 번에 알아본 건 좀 놀랍긴 하군."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "それでも一度でわかったのは、さすがに驚いたな。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Still, I'm pretty surprised that she recognized me so quickly."
L28_1.m_Talk_ENG = L29_1
L29_1 = "但我還是很驚訝她能一下子就認出來。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่ผมก็ยังแปลกใจที่เธอจำผมได้ไวเหลือเกิน"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tuy nhiên, tôi khá ngạc nhiên khi cô ấy nhận ra tôi nhanh như vậy."
L28_1.m_Talk_VTN = L29_1
L29_1 = "但就算如此，能一下子就认出来，我没想到的。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Trotzdem bin ich überrascht, dass sie mich so schnell erkannt hat."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais je suis surpris qu'elle soit parvenue à me reconnaître aussi vite."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
