L30_1 = "비상. 비상. 사옥에 침입자가 감지되었습니다. 시큐리티 시스템을 기동합니다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "非常事態発生。非常事態発生。社屋に侵入者が感知されました。セキュリティシステムを起動します。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Alert. Alert. Infiltration detected. Activating security system."
L29_1.m_Talk_ENG = L30_1
L30_1 = "緊急情況，緊急情況。偵測到公司大樓出現入侵者，保全系統啟動。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "คำเตือน คำเตือน พบการแทรกซึม เปิดระบบรักษาความปลอดภัย"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cảnh báo. Cảnh báo. Đã phát hiện xâm nhập. Kích hoạt hệ thống an ninh."
L29_1.m_Talk_VTN = L30_1
L30_1 = "紧急情况，紧急情况！检测到未知人员入侵公司大楼，启动安全系统。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Alarm. Alarm. Eindringling entdeckt. Sicherheitssystem wird aktiviert."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Alerte. Alerte. Infiltration détectée. Activation du système de sécurité."
L29_1.m_Talk_FRA = L30_1
