L32_1[L33_1] = true
L33_1 = "침식 재난은 아니군요. 또 스승님이 경보기를 걷어찬 게 아닐까 싶네요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "侵食災害ではないですね。また師匠が警報器を蹴飛ばしたのかもしれません。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Well, it's not a Corruption Disaster. Master must have kicked another alarm or something."
L32_1.m_Talk_ENG = L33_1
L33_1 = "看起來不是侵蝕災難呢，不會是師父又踢到警報器了吧？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ไม่ใช่ภัยพิบัติคอร์รัปชั่น อาจารย์คงเผลอเตะปุ่มเตือนภัยหรืออะไรสักอย่าง"
L32_1.m_Talk_THA = L33_1
L33_1 = "Chà, không phải là Thảm họa ăn mòn đâu. Chắc là Sếp lại đá vào chuông báo động nữa rồi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "看起来并不是侵蚀灾难呢，不会又是老师踢到警报器了吧？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Nun, es ist auf jeden Fall keine Verderbniskatastrophe. Die Meisterin muss mal wieder einen Alarm ausgelöst haben."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ce n'est pas un sinistre de corruption. Le maître a encore dû donner un coup dans une alarme."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
