L37_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "스승님이 심각하게 화가 났거나, 경쟁사에서 자객이라도 보낸 모양이군요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "師匠がものすごく怒ったか、ライバル会社が刺客でも送り込んだみたいですね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Okay, now Master is super angry... Or one of our competitors sent an assassin."
L36_1.m_Talk_ENG = L37_1
L37_1 = "看來不是師父在發飆，就是競爭對手派來的刺客吧。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "โอเค ตอนนี้อาจารย์โกรธมากแล้ว... หรือว่าคู่แข่งสักคนของเราส่งมือสังหารมา"
L36_1.m_Talk_THA = L37_1
L37_1 = "Được rồi, hoặc là bây giờ Sếp đang rất tức giận... Hoặc một trong những đối thủ của chúng ta đã cử đến một sát thủ."
L36_1.m_Talk_VTN = L37_1
L37_1 = "看来不是老师正在发火，就是竞争者派来的刺客吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Okay, jetzt ist die Meisterin echt sauer oder … ein Wettbewerber hat Auftragskiller geschickt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Donc soit le maître est vraiment en colère... Soit l'un de nos concurrents a envoyé un assassin."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
