L38_1 = "지금이라도 도망치시는 게 낫지 않을까요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "今からでも逃げたほうがいいんじゃないですか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Perhaps we should run while we still can?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "現在逃跑會不會比較好？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หรือเราควรจะหนีตอนที่ยังมีเวลา?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Có lẽ chúng ta nên bỏ chạy khi vẫn còn có thể?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "现在逃跑会不会更好呢？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Vielleicht sollten wir verschwinden, solange wir noch können?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Nous devrions peut-être prendre la fuite pendant qu'il en est encore temps ?"
L37_1.m_Talk_FRA = L38_1
