L40_1 = "嗯，在這之前，先讓我看看入侵者是誰。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อืมม ทำไมเราไม่ดูผู้บุกรุกคนนี้บนจอก่อนล่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hừm. Sao chúng ta không nhìn kẻ xâm nhập này qua màn hình trước đã nhỉ?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "嗯嗯，先让我看看入侵者是谁。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Hmm. Warum schauen wir uns diese Eindringlinge nicht erst mal an?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Hmm. Pourquoi ne pas d'abord vérifier à l'écran l'identité de cet intrus ?"
L39_1.m_Talk_FRA = L40_1
