L47_1.m_Pos = "C"
L47_1.m_Crash = 20
L48_1 = "후훗, 선생님. 부끄러워서 숨어 계신 건가요?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "ふふっ、先生。照れて隠れているんですか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hah hah, Teacher? Peekaboo! Are you feeling shy?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "呵呵，老師……是因為太害羞所以躲起來了嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฮ่าๆ คุณครูคะ? จ๊ะเอ๋! อายอยู่เหรอคะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ha ha, Giáo Viên? Ú òa! Anh đang cảm thấy ngại ngùng đúng không?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "呼呼，老师，是因为太害羞所以躲起来了吗。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Haha, Lehrer? Überraschung! Du bist doch nicht etwa schüchtern, oder?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ha ha, Professeur ? Coucou ! Vous êtes timide ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "COUNTERCASE_GAEUN_NORMAL_4@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31354
L48_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_DESPAIR"
L49_1 = "GAEUN_HB_VAL_BLACK"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "아니면...... 또 그때처럼 나쁜 사람들 때문에 피해 계시나요?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "それとも……またあの時みたいに悪い人たちのせいで身を潜めているんですか？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Or... Are there baddies like the last time? Are you hiding from them?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "還是說……又像那時候一樣，因為有壞人所以躲起來了？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "หรือว่า... มีพวกคนเลวแบบคราวก่อน? คุณซ่อนตัวจากพวกนั้นอยู่เหรอคะ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Hay... Bọn xấu lần trước lại xuất hiện? Anh đang trốn bọn chúng hả?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "还是说……像那时一样，因为坏人所以躲起来了？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Oder sind dir wieder irgendwelche Fieslinge auf der Spur? Versteckst du dich hier irgendwo?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ou... Est-ce qu'il y a des méchants comme la dernière fois ? Vous vous cachez ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "COUNTERCASE_GAEUN_NORMAL_4@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 31354
