L49_1.m_Face = "UNIT_LAUGH"
L50_1 = "GAEUN_HB_VAL_BLACK"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "하지만 이제 걱정하지 마세요. 선생님의 가은이가 이렇게 찾아가고 있으니까요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "でももう心配しないでください。こうして先生のユキが来ましたから。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "But don't you worry anymore. Your very own Gaeun is coming to find you."
L49_1.m_Talk_ENG = L50_1
L50_1 = "不過，現在您不用再擔心了，因為嘉恩馬上就要回到老師身邊了。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แต่ไม่ต้องกลัวแล้วนะคะ กาอึนของคุณมาหาคุณแล้วค่ะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Nhưng không cần phải lo lắng nữa. Gaeun của anh đang đến tìm anh đây."
L49_1.m_Talk_VTN = L50_1
L50_1 = "不过，现在开始您一点都不需要担心哦。因为嘉恩马上就会到老师身边去的。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Aber keine Sorge. Deine Gaeun kommt ja, um dich zu finden."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Mais ne vous inquiétez pas. Votre chère Gaeun est là pour vous sauver."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
