L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L50_1.m_Crash = 25
L51_1 = "이제...... 두 번 다시 헤어지지 않겠어요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "もう……二度と別れることはありません。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Never again... will I let anything come between us."
L50_1.m_Talk_ENG = L51_1
L51_1 = "現在……我們再也不會分開了。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "หนูจะไม่ปล่อยให้อะไร... มาขัดขวางเราอีกแล้ว"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi sẽ không để bất cứ điều gì... bất cứ điều gì xảy ra giữa chúng ta nữa."
L50_1.m_Talk_VTN = L51_1
L51_1 = "现在……我们再也不会分开了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich werde nie wieder zulassen, dass uns irgendetwas oder irgendjemand trennt."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Plus jamais... Je ne laisserai plus rien se mettre entre nous."
L50_1.m_Talk_FRA = L51_1
