L2_1 = "GAEUN_HB_VAL_BLACK"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "선생님을 괴롭히는 것들은 제가 모두 없애 드릴게요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "先生を苦しめるものは私が全部消してあげますね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I'll get rid of anything or anyone that bothers you."
L1_1.m_Talk_ENG = L2_1
L2_1 = "所有想要妨礙老師的壞人，就讓我來消滅他們吧。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "หนูจะกำจัดทุกสิ่งและทุกคนที่รบกวนคุณ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi sẽ loại bỏ bất cứ điều gì hoặc bất cứ ai làm phiền đến anh."
L1_1.m_Talk_VTN = L2_1
L2_1 = "所有想伤害老师的坏人都会由我来消灭。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich beseitige wer oder was auch immer dir Probleme macht."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je vais détruire tout ce qui vous embête."
L1_1.m_Talk_FRA = L2_1
