L4_1 = "<color=#ffd34c>레벨 4 시퀀스 준비 중. 요인의 대피를 권고합니다.</color>"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "<color=#ffd34c>レベル4シークエンス準備中。要人の避難を勧告します。</color>"
L3_1.m_Talk_JPN = L4_1
L4_1 = "<color=#ffd34c>Preparing Level 4 sequence. V.I.P. evacuation recommended.</color>"
L3_1.m_Talk_ENG = L4_1
L4_1 = "<color=#ffd34c>準備啟動4級保全系統。建議相關人員避難。</color>"
L3_1.m_Talk_TWN = L4_1
L4_1 = "<color=#ffd34c>เตรียมการระดับ 4 แนะนำให้อพยพวีไอพี</color>"
L3_1.m_Talk_THA = L4_1
L4_1 = "<color=#ffd34c>Đang chuẩn bị trình tự Cấp 4. Khuyến cáo các V.I.P nên sơ tán ngay.</color>"
L3_1.m_Talk_VTN = L4_1
L4_1 = "<color=#ffd34c>准备启动4级安全系统。建议相关人员避难。</color>"
L3_1.m_Talk_SCN = L4_1
L4_1 = "<color=#ffd34c>Bereite Stufe 4 Sequenz vor. V.I.P.-Evakuierung wird empfohlen.</color>"
