L5_1 = "COUNTERCASE_GAEUN_NORMAL_4@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31354
L4_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_LAUGH"
L5_1 = "GAEUN_HB_VAL_BLACK"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "자, 선생님. 어서 나와서 잘했다고 머리를 쓰다듬어 주세요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "さあ、先生。早く出てきて、よくやったねと頭をなでてください。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Come on, Teacher. Come on out and pat me on the head."
L4_1.m_Talk_ENG = L5_1
L5_1 = "來吧，老師，快出來誇獎我，摸摸我的頭吧。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "นะคะ คุณครู ออกมาลูบหัวหนูทีสิ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Thôi nào Giáo Viên. Hãy ra đây và xoa đầu tôi đi nào."
L4_1.m_Talk_VTN = L5_1
L5_1 = "来吧，老师，快点出来夸夸我，快来摸摸我的头吧。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Komm schon, Lehrer. Komm raus und streichel mir den Kopf."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Venez, Professeur. Venez me caresser la tête."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "COUNTERCASE_GAEUN_NORMAL_4@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 31354
L5_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L5_1.m_bWaitClick = true
