L6_1 = "GAEUN_HB_VAL_BLACK"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L5_1.m_Crash = 20
L6_1 = "제 몸도, 마음도 엉망진창으로 녹아 내릴 만큼...... 후훗♥"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "私の身も心もめちゃくちゃに溶けてしまうくらいに……ふふっ♥"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I want to feel your affection wash over me... body and soul... Teehee ♥"
L5_1.m_Talk_ENG = L6_1
L6_1 = "讓我的身體，我的心靈全都融化……呵呵♥"
L5_1.m_Talk_TWN = L6_1
L6_1 = "หนูอยากสัมผัสถึงความรักของคุณครูไปทั่วตัว... ทั้งร่างกายและจิตใจ... ฮิๆ ♥"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi muốn cảm nhận tình cảm của anh tẩy rửa cho tôi... cho cơ thể và tâm hồn tôi... Teehee ♥"
L5_1.m_Talk_VTN = L6_1
L6_1 = "让我的身体和心灵全部融化……呵呵♥"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Lass mich deine Liebe spüren. Mein Geist und mein Körper verlangen danach … Hihi ♥"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je veux sentir votre affection... corps et âme... Hi hi. ♥"
L5_1.m_Talk_FRA = L6_1
