L10_1 = "UNIT_SERIOUS"
L9_1.m_Face = L10_1
L10_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "m_bCharHologramEffect"
L9_1[L10_1] = true
L10_1 = "대체 어린 시절 만났을 때 무슨 짓을 했던 겁니까?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "幼い頃に出会った時、いったい何をしたんですか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "What the heck did you do to the kid when she was a child?!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "您到底在她小時候對她做了什麼？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นี่คุณไปทำอะไรกับเด็กคนนี้ตอนที่เธอยังเล็กเนี่ย?!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Ngài đã làm cái quái gì với đứa trẻ đó khi nó còn nhỏ vậy hả?!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "您到底在她小时候对她做过什么？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Was zum Teufel haben Sie als Kind mit ihr gemacht?!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Mais qu'est-ce que vous avez fait à cette gamine quand elle était petite ?"
L9_1.m_Talk_FRA = L10_1
