L12_1 = "COUNTERCASE_GAEUN_NORMAL_4@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31354
L11_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "ADMIN_COFFIN_NULL_QM"
L11_1.m_CharStrID = L12_1
L12_1 = "아니, 그게...... 나도 잘 모르겠는데......"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "いや、それが……私にもよくわからない……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Well, I... I have no idea either..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "不，這個……我也不知道啊……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เอ่อ ผม... ผมก็ไม่รู้เหมือนกัน..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Chà, tôi... tôi cũng không biết đâu..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "不，这个……我也不太清楚……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Nun, ähm … ich habe ehrlich gesagt auch keine Ahnung …"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je... Je l'ignore également..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "COUNTERCASE_GAEUN_NORMAL_4@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 31354
L12_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "ADMIN_COFFIN_NULL_QM"
L12_1.m_CharStrID = L13_1
L13_1 = "그, 그래도 별일 없겠지. 겉으로는 살벌해 보여도 속은 순진한 아이일 텐데......"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "まあでも、大事にはならないだろう。恐ろしいように見えても、中身は純粋な子供だから……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I-I'm sure everything will be fine. She may appear dangerous, but she's still an innocent kid inside..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "不、不過不要緊。雖然她表面上看起來殺氣騰騰，但內心卻是個天真無邪的好孩子……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ผะ-ผมมั่นใจว่าไม่มีปัญหาอะไรหรอก เธออาจดูอันตราย แต่ภายในยังคงเป็นเด็กที่ไร้เดียงสา..."
L12_1.m_Talk_THA = L13_1
L13_1 = "T-tôi chắc rằng mọi thứ sẽ ổn. Cô ấy có thể tỏ ra nguy hiểm, nhưng bên trong cô ấy vẫn là một đứa trẻ ngây thơ mà..."
L12_1.m_Talk_VTN = L13_1
L13_1 = "不，不过不要紧。虽然她表面看起来杀气腾腾，但其实是个天真无邪的好孩子，应该……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "I-ich bin sicher, alles wird gut. Sie mag gefährlich wirken, aber innerlich ist sie noch immer ein unschuldiges Kind …"
L12_1.m_Talk_DEU = L13_1
L13_1 = "J-Je suis sûr que tout ira bien. Elle a peut-être l'air dangereuse, mais au fond, c'est encore une enfant innocente..."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "COUNTERCASE_GAEUN_NORMAL_4@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 31354
L13_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_DESPAIR"
L14_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "제가 보기엔 외딴 통나무집에 감금해 두고 평생 머리만 쓰다듬으라고 할 것 같군요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私が見た感じだと、人里離れた丸太小屋に閉じ込めて、一生頭をなでさせそうですね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "From the looks of it, she'll probably keep you locked up in a remote cottage and make you pat her head for the rest of your life."
L13_1.m_Talk_ENG = L14_1
L14_1 = "在我看來，您似乎要被監禁在遠離塵世的小木屋，一輩子只能摸她的頭了。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ดูท่าแล้วเธอคงอยากจับคุณไปขังไว้ในกระท่อมห่างไกล แล้วก็ให้คุณลูบหัวเธอไปทั้งชีวิตนะคะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Theo góc nhìn hiện tại, cô ấy có thể sẽ nhốt ngài trong một ngôi nhà nhỏ hẻo lánh và buộc ngài phải xoa đầu cô ấy trong suốt quãng đời còn lại đấy."
L13_1.m_Talk_VTN = L14_1
L14_1 = "在我看来，您似乎要被抓进小黑屋，一辈子只能摸摸她的头了。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "So wie das aussieht, wird sie Sie in irgendeiner abgeschiedenen Hüte einsperren und für den Rest Ihres Lebens zwingen, ihr den Kopf zu streicheln."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Vu comment les choses se présentent, elle va sans doute vous garder enfermé dans une cabane isolée et vous forcer à lui caresser la tête jusqu'à la fin de vos jours."
L13_1.m_Talk_FRA = L14_1
