L16_1 = "ADMIN_COFFIN_NULL_QM"
L15_1.m_CharStrID = L16_1
L16_1 = "그건...... 조금 곤란하겠군."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "それは……ちょっと困るな。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Well... That could be a problem."
L15_1.m_Talk_ENG = L16_1
L16_1 = "這……這我就有點困擾了。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เอ่อ... งั้นก็จะเป็นปัญหาแล้วละ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chà... Đó mới là vấn đề đấy."
L15_1.m_Talk_VTN = L16_1
L16_1 = "这……我就有点困扰了。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Nun … das könnte ein Problem werden."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ah... Voilà qui serait problématique."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "COUNTERCASE_GAEUN_NORMAL_4@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 31354
L16_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_SERIOUS"
L16_1.m_Face = L17_1
L17_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "당장 제가 가겠습니다. 그동안 사장실에 꼭 숨어 있도록 하세요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "今すぐ私が行きます。それまで社長室にしっかり隠れていてください。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I'll go take care of this right now. In the mean time, stay hidden in your office."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我馬上就過去。這段時間請您好好躲在老闆辦公室。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฉันจะไปจัดการเดี๋ยวนี้ ระหว่างนี้ก็ซ่อนตัวอยู่ในห้องทำงานนะคะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi sẽ giải quyết việc này ngay bây giờ. Trong lúc đó, hãy trốn trong văn phòng của ngài đi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我马上就过去，这段时间请好好躲在办公室。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich gehe jetzt und kümmer mich darum. Verstecken Sie sich weiter hier im Büro."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Je vais m'occuper d'elle. En attendant, restez caché dans votre bureau."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
