L23_1 = "UNIT_IDLE"
L22_1.m_Face = L23_1
L23_1 = "GAEUN_HB_VAL_BLACK"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "응? 선생님과 저의 만남을 방해하는 문짝이 있네요?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "うん？　先生と私の再会を邪魔するドアがありますね？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Huh? There's a door getting in the way of our lovely reunion!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "嗯？有扇妨礙我和老師見面的門呢。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "หืม? มีประตูมาขวางทางพบรักของเรา!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Huh? Có một cánh cửa đang cản trở cuộc hội ngộ dễ thương của chúng ta!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "嗯？有扇妨碍我和老师见面的门呢？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Was? Diese Tür steht unserem romantischen Wiedersehen im Weg!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Quoi ? Une porte se dresse entre nous et notre douce réunion !"
L22_1.m_Talk_FRA = L23_1
