L24_1 = "GAEUN_HB_VAL_BLACK"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "이런 나쁜 문짝은 사랑과 마법의 힘으로 벌을 줘야겠죠?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "こんな悪いドアは愛と魔法の力で懲らしめてあげないとダメですね？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "A naughty door like this ought to be punished with my spell of love!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "這種壞門，就應該用愛之魔法給予懲罰吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ประตูร้ายๆ แบบนี้ต้องถูกลงโทษด้วยคาถาแห่งรักของฉัน!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Một cánh cửa nghịch ngợm như thế này phải bị trừng phạt bằng bùa yêu của tôi!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "这种坏门，就应该用我的爱与魔法好好惩罚一下呢。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "So eine fiese und gemeine Tür! Die kriegt meinen Liebeszauber zu spüren."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Une vilaine porte comme celle-ci mérite d'être punie par la force de mon amour !"
L23_1.m_Talk_FRA = L24_1
