L32_1 = "후훗...... 이런 얇은 장막으로는 선생님과 저의 사이를 갈라놓을 수 없는 걸요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ふふっ……こんなに弱い壁では、先生と私の仲を引き裂くことはできないんです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Heh heh... A flimsy door like this couldn't possibly stand in the way of my reunion with you, Teacher."
L31_1.m_Talk_ENG = L32_1
L32_1 = "呵呵……這種淺薄的隔閡是無法分開我和老師的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฮิๆ... ประตูบางๆ แบบนี้ไม่มีทางขัดขวางไม่ให้เราพบกันได้หรอกค่ะ คุณครู"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hơ hơ... Một cánh cửa mỏng manh không thể cản trở cuộc hội ngộ của tôi với anh đâu, Giáo Viên à."
L31_1.m_Talk_VTN = L32_1
L32_1 = "呵呵……这种薄薄的隔阂是无法分开我和老师的。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hehe … So eine mickrige Tür kann unser Wiedersehen nicht verhindern, Lehrer."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Hé hé... Ce n'est pas une petite porte comme celle-ci qui va m'empêcher de vous retrouver, Professeur."
L31_1.m_Talk_FRA = L32_1
