L36_1 = "ตายจริง นี่ใครอีกล่ะ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ôi trời, và giờ là ai đây?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "哎呀，这是谁啊？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Auweia, wer ist das denn?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oh, qui c'est, elle ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "COUNTERCASE_GAEUN_NORMAL_4@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 31354
L36_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "GAEUN_HB_VAL_BLACK"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "후후훗, 역시 제가 없는 동안 선생님께 꼬리 치는 여우들이 잔뜩 달라붙었네요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ふふふっ、やっぱり私がいない間に、先生を誘惑するキツネたちがくっついてたんですね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Hah hah, looks like some naughty vixens thought they'd have a chance with you without me around."
L36_1.m_Talk_ENG = L37_1
L37_1 = "呵呵呵，果然我不在的時候，有很多纏上老師的狐狸精呢。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฮ่าๆ มียัยตัวร้ายบางคนคิดว่าจะมีโอกาสกับคุณพอไม่มีหนูอยู่สินะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ha ha, có vẻ như một số phụ nữ xấu xa nghĩ rằng họ sẽ có cơ hội với ngài khi không có tôi ở bên."
L36_1.m_Talk_VTN = L37_1
L37_1 = "呵呵呵，果然我不在的时候，有很多缠上老师的狐狸精啊。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Haha, anscheinend haben einige Luder gedacht, sie hätten eine Chance bei dir, solange ich nicht da bin."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ha ha, on dirait qu'une vilaine séductrice pensait avoir une chance avec vous quand je n'étais pas là."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "COUNTERCASE_GAEUN_NORMAL_4@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31354
L37_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L38_1 = "GAEUN_HB_VAL_BLACK"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "하지만 곤란해요, 선생님 곁에 있어야 하는 사람은 저 혼자로 충분하거든요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "でも困りますよ、先生の隣にいるべき人は私一人で十分なんです。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But this won't do at all. There can only be one lady next to you, Teacher."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不過這真是困擾呢。陪在老師旁邊的，只要有我一個人就夠了。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่ไม่ได้ผลหรอก มีผู้หญิงคนเดียวเท่านั้นที่จะอยู่ข้างคุณได้ค่ะ คุณครู"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nhưng sẽ chẳng có tác dụng gì đâu. Bên cạnh Giáo Viên chỉ có thể có một người."
L37_1.m_Talk_VTN = L38_1
L38_1 = "不过没关系，老师只要有我一个人就够了。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Aber so geht das nicht. Es kann nur eine Dame an deiner Seite geben, Lehrer."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Mais je ne vais pas la laisser faire. Il ne peut y avoir qu'une femme à vos côtés, Professeur."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_GAEUN_NORMAL_4@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31354
L38_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "UNIT_SERIOUS"
L38_1.m_Face = L39_1
L39_1 = "GAEUN_HB_VAL_BLACK"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L38_1.m_Crash = 30
L39_1 = "선생님의 쓰담쓰담은 제 거에요. 당신 같은 여우에게는 양보 못해."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "先生のなでなでは私のものです。あなたみたいなキツネには絶対譲れない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Only I get to get my head patted by you, Teacher. Not some vixen like this!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "老師的摸摸頭只屬於我，我是不會讓給妳這隻狐狸精的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "หนูเท่านั้นที่จะถูกคุณลูบหัวนะคะ ไม่ใช่นังจิ้งจอกคนนี้!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Chỉ có tôi mới có thể được Giáo Viên xoa đầu. Chứ không phải bà già như thế này!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "老师只能摸我的头，我是不会让给你这只狐狸精的。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Nur mir darfst du den Kopf streicheln, Lehrer. Nicht diesen Ludern."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je suis la seule à pouvoir recevoir des caresses sur la tête, Professeur. Pas une séductrice dans son genre !"
L38_1.m_Talk_FRA = L39_1
