L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "ADMIN_COFFIN_NULL_QM"
L41_1.m_CharStrID = L42_1
L42_1 = "어...... 혹시 자네도 내가 쓰다듬어 주길 바라고 있었나?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "え……ひょっとして君も私になでてほしいと思っていたのか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Um... Did you want me to pat your head, by any chance?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "呃……妳該不會也想被我摸摸頭吧？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เอ่อ... คุณอยากให้ผมลูบหัวคุณมั้ย?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Ừm... Bạn muốn tôi xoa đầu không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "啊……难道说你也想被我摸摸头吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Hmm … Mögen Sie es vielleicht, wenn ich Ihnen den Kopf streichel?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Euh... Vouliez-vous que je vous caresse la tête, par hasard ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_GAEUN_NORMAL_4@192#Talk"
