L42_1.m_Face = "UNIT_LAUGH"
L43_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L42_1.m_Crash = 20
L43_1 = "당장 그 손 치우시죠. 팔째로 날아가기 싫으시면요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "今すぐその手を離してください。腕ごと吹き飛ばされたくなかったら。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Take your stinking hand off me. If you don't want me to blow off your entire arm."
L42_1.m_Talk_ENG = L43_1
L43_1 = "立刻把你的手拿開，如果你不想少條手臂的話。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เอามือเหม็นๆ ของคุณออกไปซะ ถ้าไม่อยากถูกฉันระเบิดแขนทิ้ง"
L42_1.m_Talk_THA = L43_1
L43_1 = "Bỏ bàn tay hôi hám của ngài ra khỏi người tôi. Nếu ngài không muốn tôi bắn đứt toàn bộ cánh tay đó."
L42_1.m_Talk_VTN = L43_1
L43_1 = "立即住手，如果你不想缺胳膊少腿的话。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Nehmen Sie sofort Ihre stinkende Hand weg. Sonst spreng ich den ganzen Arm ab."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ôtez vos sales pattes si vous ne voulez pas que je vous fasse sauter le bras."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
