L44_1.m_Pos = "C"
L45_1 = "걱정하지 마세요, 선생님. 이제부터는 제가 안전하게 지켜 드릴게요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "心配しないでください、先生。これからは私が安全にお守りしますからね。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Don't worry, Teacher. I'll keep you safe from now on."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不要擔心，老師。從現在開始，我會好好保護您的。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ไม่ต้องห่วงค่ะ คุณครู จากนี้หนูจะปกป้องคุณเอง"
L44_1.m_Talk_THA = L45_1
L45_1 = "Đừng lo lắng, Giáo Viên. Từ giờ tôi sẽ bảo đảm an toàn cho anh."
L44_1.m_Talk_VTN = L45_1
L45_1 = "老师，不用担心哦。从现在开始，我会好好保护你。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Keine Sorge, Lehrer. Ab jetzt pass ich auf dich auf."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ne vous inquiétez pas, Professeur. Je vais vous protéger à partir de maintenant."
L44_1.m_Talk_FRA = L45_1
