L49_1 = "ADMIN_COFFIN_NULL_QM"
L48_1.m_CharStrID = L49_1
L49_1 = "......시, 식은땀이 흐르는 건 오랜만이군."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……ひ、冷や汗をかくなんて久しぶりだな。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I-it's been a while since I've been this nervous."
L48_1.m_Talk_ENG = L49_1
L49_1 = "……好、好久沒流這麼多冷汗了。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "นะ-นานแล้วนะที่ผมไม่ได้ประหม่าขนาดนี้"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đ-đã lâu rồi mình không thấy lo lắng như thế này."
L48_1.m_Talk_VTN = L49_1
L49_1 = "……好，好久没流过这么多冷汗了。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "I-ist schon eine Weile her, dass ich so nervös war wie jetzt."
L48_1.m_Talk_DEU = L49_1
L49_1 = "V-Voilà longtemps que je n'avais pas été aussi nerveux."
L48_1.m_Talk_FRA = L49_1
