L50_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "당신도 참 죄 많은 사람이로군요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "あなたも本当に罪深い人ですね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You sure do have a lot of skeletons in your closet."
L49_1.m_Talk_ENG = L50_1
L50_1 = "您可真是個罪孽深重的人啊。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "คุณทำอะไรลับๆ ล่อๆ มาเยอะสินะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Chắc chắn là ngài cất giữ nhiều bí mật lắm nhỉ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "您可真是个罪孽深重的人啊。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Sie haben sicher viele Leichen im Keller."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Vous avez vraiment beaucoup de cadavres dans le placard."
L49_1.m_Talk_FRA = L50_1
