L2_1 = "GAEUN_HB_VAL_BLACK"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L1_1.m_Crash = 15
L2_1 = "저를 꼭 끌어안아서 그 따뜻한 체온도, 부드러운 손길도, 전부 느낄 수 있게......♥"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ぎゅっと抱きしめて温かい体温も、優しい手つきも、全部感じられるように……♥"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Hold me tight so I can feel your warm embrace, your loving touch, all of it... ♥"
L1_1.m_Talk_ENG = L2_1
L2_1 = "緊緊抱住我，讓我感受您的體溫，您柔軟的手，還有您的全部……♥"
L1_1.m_Talk_TWN = L2_1
L2_1 = "กอดหนูไว้แน่ๆ ให้หนูได้สัมผัสอ้อมกอดอันอบอุ่นของคุณ สัมผัสรักของคุณ ทุกอย่างเลย... ♥"
L1_1.m_Talk_THA = L2_1
L2_1 = "Hãy ôm tôi thật chặt để tôi có thể cảm nhận được vòng tay ấm áp của anh, sự yêu thương của anh, tất cả những thứ đó... ♥"
L1_1.m_Talk_VTN = L2_1
L2_1 = "紧紧抱住我，让我感受您的体温，您柔软的手，还有您的全部……♥"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Halt mich fest, wärme mich mit deiner Umarmung und deinen Liebkosungen. Gib mir alles, wonach ich mich sehne … ♥"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Serrez-moi fort contre vous. Laissez-moi sentir votre douce étreinte pleine d'amour... ♥"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "COUNTERCASE_GAEUN_NORMAL_4@202#Talk"
