L3_1 = "UNIT_SERIOUS"
L2_1.m_Face = L3_1
L3_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "일단 뒤로 물러서시죠. 제가 막겠습니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "とりあえず後ろに下がっていてください。私が止めます。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Why don't you get behind me for now. I'll fend her off."
L2_1.m_Talk_ENG = L3_1
L3_1 = "您先退後，我來擋住她。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ไปหลบหลังฉันสิ ฉันจะไล่เธอไปเอง"
L2_1.m_Talk_THA = L3_1
L3_1 = "Sao ngài không đứng sau tôi đi nhỉ. Tôi sẽ cầm cự với cô ấy."
L2_1.m_Talk_VTN = L3_1
L3_1 = "您先退后，我来挡住她。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Wie wäre es, wenn Sie sich hinter mir verstecken? Ich werde sie schon in Schach halten."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Vous devriez rester derrière moi pour le moment. Je vais la retenir."
L2_1.m_Talk_FRA = L3_1
