L8_1 = "COUNTERCASE_GAEUN_NORMAL_4@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 31354
L7_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "ADMIN_COFFIN_NULL_QM"
L7_1.m_CharStrID = L8_1
L8_1 = "영문은 모르겠지만...... 저 아이가 저렇게까지 된 건 나 때문이야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "理由はわからないが……あの子があんなふうになったのは私のせいだ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I don't know how it's come to this... But I'm responsible for her being this way."
L7_1.m_Talk_ENG = L8_1
L8_1 = "雖然不知道事情的起因……但那孩子會變成那樣，都是我的錯。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ผมไม่รู้ว่ามันเป็นแบบนี้ได้ยังไง... แต่ผมต้องรับผิดชอบที่เธอเป็นแบบนี้"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi không biết tại sao mọi chuyện lại đi đến mức này... Nhưng tôi phải chịu trách nhiệm."
L7_1.m_Talk_VTN = L8_1
L8_1 = "虽然不知道事情的起因……但那孩子会变成那样是因为我。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich weiß nicht, wie es dazu gekommen ist … Aber ich bin dafür verantwortlich, dass sie so geworden ist."
L7_1.m_Talk_DEU = L8_1
L8_1 = "J'ignore comment nous en sommes arrivés là... Mais je suis responsable de son comportement actuel."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "COUNTERCASE_GAEUN_NORMAL_4@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 31354
L8_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "ADMIN_COFFIN_NULL_QM"
L8_1.m_CharStrID = L9_1
L9_1 = "그러니 내가 어떻게든 달래 봐야지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "だから私がどうにかしてでもなだめないと。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "So I should try to calm her down somehow."
L8_1.m_Talk_ENG = L9_1
L9_1 = "所以我得想辦法去安撫她。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ผมควรจะลองทำให้เธอสงบลง"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vậy nên tôi muốn thử làm cô ấy bình tĩnh lại."
L8_1.m_Talk_VTN = L9_1
L9_1 = "所以我必须亲自面对她。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Also muss ich sie auch irgendwie wieder beruhigen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je devrais essayer de la calmer."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "COUNTERCASE_GAEUN_NORMAL_4@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 31354
L9_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_DESPAIR"
L10_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "이미 눈에 뵈는 게 없는 상태입니다. 가능하다고 생각하시나요?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "すでに理性を失っている状態です。それが可能だと思いますか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "She's already unstoppable. Do you think it's really possible?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "她已經被某種東西蒙蔽了雙眼，您覺得有可能安撫她嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เธอหยุดไม่อยู่แล้วค่ะ คิดว่าจะทำได้จริงๆ เหรอคะ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Không thể ngăn cản cô ấy lại được. Ngài thực sự nghĩ mình có thể làm chuyện đó à?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "她现在已经被某种东西蒙蔽了双眼，您觉得能顺利解决吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Sie ist unaufhaltsam, glauben Sie wirklich, das gelingt Ihnen?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Elle est déjà impossible à arrêter. Vous pensez vraiment que c'est faisable ?"
L9_1.m_Talk_FRA = L10_1
