L14_1 = "COUNTERCASE_GAEUN_NORMAL_4@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 31354
L13_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "UNIT_IDLE"
L13_1.m_Face = L14_1
L14_1 = "GAEUN_HB_VAL_BLACK"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "후훗, 역시 선생님...... 여우들이 저희 사이를 방해해도 제 진심을 알아 주시네요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ふふっ、やっぱり先生……キツネたちが邪魔しても、私の気持ちをわかってくれるんですね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Hah hah, I knew I could count on you, Teacher... Please accept my true feelings for you, no matter how much those vixens try to get in our way."
L13_1.m_Talk_ENG = L14_1
L14_1 = "呵呵，不愧是老師……即使有狐狸精阻礙了我們，您還是知道我的心意呢。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฮ่าๆ หนูรู้อยู่แล้วว่าหนูพึ่งคุณได้ค่ะ คุณครู... ตอบรับความรู้สึกที่หนูมีต่อคุณหน่อยนะคะ ไม่ว่าจะมีจิ้งจอกอีกกี่ตัวที่พยายามเข้ามาแทรกแซงเรา"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ha ha, tôi biết tôi có thể tin tưởng vào anh mà, Giáo Viên... Xin hãy chấp nhận tình cảm chân thành mà tôi đã dành cho anh, dù những bà già đó cố gắng cản đường chúng ta đến mức nào."
L13_1.m_Talk_VTN = L14_1
L14_1 = "呼呼，果然是老师……即便有狐狸精阻碍在我们之间，您也可以理解我的真心呢。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Haha, Lehrer, ich wusste, dass ich auf dich zählen kann … Bitte akzeptiere meine wahren Gefühle, egal wie sehr diese Luder uns auseinander bringen wollen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ha ha, je savais que je pouvais compter sur vous, Professeur. S'il vous plaît, acceptez mes sentiments pour vous, peu importe combien de séductrices se dressent entre nous."
L13_1.m_Talk_FRA = L14_1
