L16_1 = "그래, 가은 양. 머리를 쓰다듬어 달라고 했지."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ああ、ユキさん。頭をなでてほしいと言ったな。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Yes, Gaeun. So you wanted me to pat you on the head."
L15_1.m_Talk_ENG = L16_1
L16_1 = "是啊，嘉恩小姐，妳想讓我摸摸頭是吧。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ใช่ กาอึน เธออยากให้ฉันลูบหัวเธอสินะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đúng thế, Gaeun. Vậy bạn muốn tôi xoa đầu bạn."
L15_1.m_Talk_VTN = L16_1
L16_1 = "是啊，嘉恩小姐，你想让我摸摸你的头是吧。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ja, Gaeun. Du wolltest, dass ich dir über den Kopf streichel, oder?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Oui, Gaeun. Tu voulais que je te caresse la tête."
L15_1.m_Talk_FRA = L16_1
