L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 31354
L28_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "UNIT_IDLE"
L28_1.m_Face = L29_1
L29_1 = "GAEUN_HB_VAL_BLACK"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "후훗, 알았다~ 다른 여우들의 시선이 불쾌하신 거죠?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ふふっ、わかった～。他のキツネたちの視線が気になるんですね？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Oh, I know what it is. You're uncomfortable about the other vixens watching, right?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "呵呵，我知道了～您在意其他狐狸精的視線對吧？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อ๊ะ หนูเข้าใจแล้วค่ะ คุณไม่สบายใจเพราะมีนักจิ้งจอกมองอยู่ใช่มั้ยคะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ồ, tôi biết rồi. Anh không thoải mái khi bị mấy bà già chứng kiến, phải không?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "呼呼，我知道了~ 您在意其他狐狸精的视线是吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Oh, ich weiß, was los ist. Du fühlst dich unwohl, weil die Luder da zuschauen, oder?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Oh, je sais quel est le problème. Vous êtes gêné parce que l'autre séductrice nous regarde, c'est ça ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "COUNTERCASE_GAEUN_NORMAL_4@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 31354
L29_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_PRIDE"
L30_1 = "GAEUN_HB_VAL_BLACK"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "괜찮아요. 저희 둘이서 오붓하게 지낼 수 있는 곳으로 모셔다 드릴게요, 선생님."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "大丈夫ですよ。二人だけで静かに過ごせる場所にお連れしますからね、先生。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Don't worry. I'll take you somewhere where we can be together, just the two of us."
L29_1.m_Talk_ENG = L30_1
L30_1 = "沒關係，那就去一個只有我們兩個人的平靜地方吧，老師。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ไม่ต้องห่วงค่ะ หนูจะไปคุณไปที่ที่มีแต่เรา แค่เราสองคน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đừng lo lắng. Hãy đưa tôi đến một nơi mà chúng ta có thể ở bên nhau, chỉ hai chúng ta thôi."
L29_1.m_Talk_VTN = L30_1
L30_1 = "没事。那么就去一个只有我们两人的世外天堂吧，老师。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Keine Sorge. Ich bringe dich an einen Ort, wo wir ungestört sein können. Nur wir beide."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ne vous en faites pas. Je vais vous emmener à un endroit où nous pourrons être ensemble, rien que vous et moi."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "COUNTERCASE_GAEUN_NORMAL_4@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 31354
L30_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "UNIT_IDLE"
L30_1.m_Face = L31_1
L31_1 = "GAEUN_HB_VAL_BLACK"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "그곳에선 제가 하나부터 열까지 곁에서 챙겨 드리고...... 기쁘게 해 드릴 테니까요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そこでは私が何から何までそばでお世話して……喜ばせてあげますから。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I'll tend to your every need there... and keep you satisfied."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我會把您照顧得無微不至……讓您快快樂樂沒煩惱。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "หนูจะทำทุกอย่างที่คุณต้องการ... ทำให้คุณพึงพอใจ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi sẽ đáp ứng mọi nhu cầu của anh... và giúp anh hài lòng."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我会从头到尾好好照顾您……我会让您很高兴的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Dort werde ich dir jeden Wunsch erfüllen …"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je m'occuperai de tout pour vous... absolument tout."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
