L31_1.m_Talk_ENG = L32_1
L32_1 = "就算要把我的一切都奉獻給您……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ต่อให้หนูต้องยอมสละทุกอย่าง..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Cho dù phải hy sinh tất cả..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "就算把我的一切都奉献给您……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Auch wenn ich alles dafür opfern muss …"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Même si je dois tout sacrifier..."
L31_1.m_Talk_FRA = L32_1
