L38_1.m_Pos = "C"
L38_1.m_Crash = 30
L39_1 = "왜...... 이런 곳에......? 게다가 이 부끄러운 복장은 대체......?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "どうして……こんな所に……？　それに、この恥ずかしい服装は何なの……？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "What am I... doing here? And what's with this embarrassing outfit?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "我為什麼……在這裡……？這羞恥的衣服，到底是……？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "นี่ฉัน... ทำอะไรอยู่ที่นี่? แล้วชุดน่าอายนี่มันอะไรกัน?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi... đang làm gì ở đây vậy? Và bộ trang phục đáng xấu hổ này là sao?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "我为什么……在这里……？这羞耻的衣服到底是……？"
