L41_1 = "ADMIN_COFFIN_NULL_QM"
L40_1.m_CharStrID = L41_1
L41_1 = "저, 정신이 들었나. 어떻게 된 일인지는 모르겠지만 다행이야."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "き、気がついたか。どういうことなのかわからないが、本当によかったよ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "H-have you come to your senses? I'm not sure what happened, but thank goodness."
L40_1.m_Talk_ENG = L41_1
L41_1 = "妳、妳終於清醒了。雖然不知道發生了什麼，但真是太好了。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ดะ-ได้สติแล้วเหรอ? ฉันไม่แน่ใจว่าเกิดอะไรขึ้น แต่ขอบคุณพระเจ้า"
L40_1.m_Talk_THA = L41_1
L41_1 = "B-bạn đã tỉnh táo lại rồi hả? Tôi không chắc chuyện gì đã xảy ra, nhưng cảm ơn trời đất."
L40_1.m_Talk_VTN = L41_1
L41_1 = "你，你终于清醒了啊。虽然不知道发生了什么，但你没事就好。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Oh, du bist wohl wieder bei klarem Verstand! Ich weiß nicht, was passiert ist, aber Gott sei Dank."
L40_1.m_Talk_DEU = L41_1
L41_1 = "T-Tu as repris tes esprits ? Je ne suis pas certain de savoir ce qui est arrivé, mais c'est un soulagement."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
