L42_1 = "That voice... Is it you... Teacher?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "這聲音是……難道是老……老師？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เสียงนั้น... ใช่คุณเหรอคะ... คุณครู?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Giọng nói đó... Có phải là anh không... Giáo Viên?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "这声音是……难道是老……老师？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Diese Stimme … bist du das … Lehrer?"
