L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_DESPAIR"
L43_1 = "GAEUN_HB_VAL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L42_1.m_Crash = 25
L43_1 = "아, 안 돼. 이런 부끄러운 모습으로 뵙고 싶지는 않았...... 는데......"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "い、いや……こんな恥ずかしい姿でお会いしたくなかった……のに……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "N-no... I'm so embarrassed... This wasn't what I had in mind..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "不、不要。我不想用這麼羞恥的模樣……來見您……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มะ-ไม่สิ... หนูอายจังเลย... นี่ไม่ใช่อย่างที่หนูคิดนะคะ..."
L42_1.m_Talk_THA = L43_1
L43_1 = "K-không... tôi xấu hổ quá... Đây không phải là những gì tôi đã nghĩ..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "不，不行。我不想让您看到我这么羞耻……的样子……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "N-nein … Oh, das ist so peinlich … Das ist ganz sicher nicht, was ich mir vorgestellt habe."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh, non... Je suis tellement gênée... Ce n'était pas ce que j'avais imaginé..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
