L45_1 = "COUNTERCASE_GAEUN_NORMAL_4@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31354
L44_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_DESPAIR"
L45_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "......기절했군요. 정신을 잃을 만큼 부끄러웠나 보네요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "……気絶しましたね。気を失うくらい恥ずかしかったようです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "She passed out. I guess she was embarrassed enough to pass out."
L44_1.m_Talk_ENG = L45_1
L45_1 = "……昏過去了。看來是害羞到昏過去了呢。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เธอหมดสติไปแล้ว สงสัยจะอายจนเป็นลม"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô ấy ngất rồi. Tôi đoán cô ấy xấu hổ đến mức ngất xỉu đấy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "……晕过去了。看来是害羞到晕过去了呢。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Sie ist ohnmächtig geworden. Ohnmächtig vor Peinlichkeit."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Elle s'est évanouie. Je suppose que sa gêne lui a fait perdre conscience."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
