L47_1 = "COUNTERCASE_GAEUN_NORMAL_4@246#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 246
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 31354
L46_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "ADMIN_COFFIN_NULL_QM"
L46_1.m_CharStrID = L47_1
L47_1 = "십년감수했군. 일단은 보호자에게 연락해 주겠나?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "寿命が縮んだよ。とりあえず保護者に連絡してくれるか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "That was close. Could you get in touch with her legal guardian for now?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "我覺得我的壽命少了十年。總之，妳能聯絡到監護人嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เกือบไปแล้วเชียว นี่คุณติดต่อผู้ปกครองเธอได้มั้ย?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Suýt tí nữa thì toi. Bạn có thể liên lạc với người giám hộ hợp pháp của cô ấy không?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "好险啊。总之，能先联系到监护人吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Das war knapp. Nehmen Sie bitte Kontakt mit ihrem gesetzlichen Vertreter auf?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "C'était moins une. Pourriez-vous contacter son tuteur légal ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_GAEUN_NORMAL_4@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 31354
L47_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ADMIN_COFFIN_NULL_QM"
L47_1.m_CharStrID = L48_1
L48_1 = "병원 쪽도 수소문해서 정밀검사도 받을 수 있게 해 주게."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あと病院を手配して、精密検査も受けられるようにしてくれ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "And call the hospital and see if she needs to get some tests done as well."
L47_1.m_Talk_ENG = L48_1
L48_1 = "同時醫院那邊也聯絡一下，好讓她能接受精密的檢查。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แล้วก็โทรไปที่โรงพยาบาล เผื่อว่าเธอต้องตรวจร่างกายอะไรด้วย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Và gọi cho bệnh viện để xem liệu cô ấy có cần làm một số xét nghiệm hay không nữa nhé."
L47_1.m_Talk_VTN = L48_1
L48_1 = "医院那边也联系一下，好让她接受精密检查。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Und rufen Sie auch im Krankenhaus an, vielleicht braucht sie eine Untersuchung."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Et appelez un hôpital pour vérifier si elle doit passer des examens."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "COUNTERCASE_GAEUN_NORMAL_4@248#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31354
L48_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "ADMIN_COFFIN_NULL_QM"
L48_1.m_CharStrID = L49_1
L49_1 = "가벼운 저주...... 그러니까 CRF 쇼크인 것 같은데 혹시 모르니까."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "軽い呪い……つまりCRFショックのようだが、念のためにな。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "It seems to be a light curse of some kind... as in a CRF shock. But you never know."
L48_1.m_Talk_ENG = L49_1
L49_1 = "輕微的詛咒……這有可能是CRF休克，但以防萬一。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ดูเหมือนเป็นคำสาปเบาๆ นะคะ... เหมือนการช็อก CRF แต่เราไม่มีทางรู้หรอก"
L48_1.m_Talk_THA = L49_1
L49_1 = "Có vẻ như đây là một lời nguyền nhẹ... như trong một cú sốc CRF vậy. Nhưng bạn không bao giờ biết được đâu."
L48_1.m_Talk_VTN = L49_1
L49_1 = "轻微的诅咒……这有可能是CRF休克，但以防万一。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Es wirkt wie ein leichter Fluch … Aber man weiß ja nie."
L48_1.m_Talk_DEU = L49_1
L49_1 = "On dirait une malédiction mineure... comme un choc FRC. Mais on ne sait jamais."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
