L2_1 = "ADMIN_COFFIN_NULL_QM"
L1_1.m_CharStrID = L2_1
L2_1 = "음? 뭔가 할말이라도 있나?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "うん？　何か言いたいことでもあるのか？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Hmm? Did you want to say something?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "嗯？妳有什麼想說的嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "หืมม? อยากพูดอะไรเหรอ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Hmm? Bạn muốn nói gì sao?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "嗯？你有什么想说的吗？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Hm? Sie wollten noch etwas sagen?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Hmm ? Vous avez quelque chose à me dire ?"
L1_1.m_Talk_FRA = L2_1
