L3_1 = "UNIT_IDLE"
L2_1.m_Face = L3_1
L3_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "이런 식으로 덮어 봐야 같은 일이 반복될 뿐입니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "こうしてうやむやにしても同じことが繰り返されるだけです。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Covering this up will only cause it to happen again, eventually."
L2_1.m_Talk_ENG = L3_1
L3_1 = "您要是還想繼續隱瞞下去，只會讓今天的事情再度重演。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ถ้าเราปิดเรื่องนี้ มันก็มีแต่จะเกิดขึ้นอีกครั้งนะคะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Che giấu sẽ chỉ khiến chuyện này xảy ra một lần nữa."
L2_1.m_Talk_VTN = L3_1
L3_1 = "您要是还想掩盖下去，只会让今天的事情重演。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Die Sache zu vertuschen, wird nur dazu führen, dass es früher oder später wieder passiert."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Si vous tentez de cacher ce qui s'est passé, la situation va se répéter tôt ou tard."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "COUNTERCASE_GAEUN_NORMAL_4@253#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 253
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 31354
