L4_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "차라리 솔직하게 이야기하시는 건 어떨까요?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "いっそのこと正直にお話してはどうでしょうか？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Why don't you just be honest with her instead?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "不如直接坦誠相見怎麼樣？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ทำไมไม่พูดกับเธอตามตรงล่ะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Thay vào đó, sao ngài không thành thật nhỉ?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "不如直接坦诚相见怎么样？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Warum sind Sie nicht einfach ehrlich zu ihr?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Pourquoi ne pas simplement lui dire la vérité ?"
L3_1.m_Talk_FRA = L4_1
