L6_1 = "ADMIN_COFFIN_NULL_QM"
L5_1.m_CharStrID = L6_1
L6_1 = "농담이겠지? 간신히 평범한 삶을 찾은 아이를 내 곁에 두면 무슨 일이 생길지 알지 않나?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "冗談だろ？　やっと平凡な日常を取り戻した子を私のそばに置いたらどうなるか、君もわかるじゃないか。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "You're kidding, right? She just barely managed to get her life back. Who knows what would happen if I let her stay with me?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "妳在開玩笑吧？這孩子好不容易能過普通生活，妳不知道她跟我在一起會發生什麼事嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ล้อเล่นใช่มั้ย? เธอแทบเอาชีวิตไม่รอด ใครจะไปรู้ว่าจะเกิดอะไรขึ้น ถ้าให้เธออยู่กับผม?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Bạn đang đùa, phải không? Cô ấy chỉ mới có được cuộc sống của mình. Ai biết được chuyện gì sẽ xảy ra nếu tôi để cô ấy ở lại cạnh tôi cơ chứ?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "你开玩笑吧？这孩子好不容易能过普通生活，你知道她如果和我在一起会发生什么吗？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Sie machen wohl Witze, oder? Sie hat gerade erst ihr Leben zurück. Nicht auszudenken, was passieren könnte, wenn ich ihr erlaube, bei mir zu bleiben."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Vous plaisantez ? Elle vient à peine de retrouver une vie normale. Qui sait ce qui pourrait lui arriver si elle reste avec moi ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "COUNTERCASE_GAEUN_NORMAL_4@256#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 256
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 31354
L6_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_4"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "그렇긴 합니다만, 그 아이가 원하는 게 뭔지도 생각해 보시면 좋을 것 같네요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そうですが、あの子が望んでいることが何かを考えてみるといいかもしれません。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I understand that, but perhaps you should think about what she wants."
L6_1.m_Talk_ENG = L7_1
L7_1 = "話是沒有錯，但是您還是得思考看看，那個孩子要的究竟是什麼。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉันเข้าใจค่ะ แต่บางทีคุณน่าจะลองคิดถึงสิ่งที่เธอต้องการบ้าง"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi hiểu điều đó, nhưng có lẽ ngài nên nghĩ xem thứ cô ấy muốn là gì."
L6_1.m_Talk_VTN = L7_1
L7_1 = "确实是这样，但您应该考虑一下她的感受。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Das verstehe ich, aber vielleicht sollten Sie auch ihre Wünsche in Betracht ziehen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je comprends bien, mais vous devriez peut-être songer à ce qu'elle veut."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "COUNTERCASE_GAEUN_NORMAL_4@257#Talk"
L7_1.m_CutScenKey_Talk = L8_1
