L8_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "사람의 마음이란 건 밀어내기만 한다고 능사는 아니니까요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "人の心は、突き放せば終わりというわけにもいきませんから。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Turning people away doesn't solve everything, especially when it comes to personal feelings."
L7_1.m_Talk_ENG = L8_1
L8_1 = "一直拒絕別人的心意可不是什麼好事情。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "การปฏิเสธคนไม่ได้แก้ไขปัญหาทุกอย่างหรอกค่ะ โดยเฉพาะถ้าเป็นเรื่องความรู้สึกคน"
L7_1.m_Talk_THA = L8_1
L8_1 = "Quay lưng lại với mọi người không giải quyết được mọi chuyện đâu, đặc biệt là những chuyện liên quan đến cảm xúc cá nhân."
L7_1.m_Talk_VTN = L8_1
L8_1 = "一直拒绝他人的心意可不是什么好办法。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Leute abzuweisen löst nicht alle Probleme, besonders wenn es um persönliche Gefühle geht."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Rejeter les gens ne mène à rien, surtout lorsqu'il s'agit de sentiments personnels."
L7_1.m_Talk_FRA = L8_1
